window.QUESTIONS=[{"number":1,"question":"In Deutschland dürfen Menschen offen etwas gegen die Regierung sagen, weil …","answers":["hier Religionsfreiheit gilt.","die Menschen Steuern zahlen.","die Menschen das Wahlrecht haben.","hier Meinungsfreiheit gilt."],"correct":3,"explanation":"Artikel 5 des Grundgesetzes garantiert die Meinungsfreiheit. Kritik an der Regierung ist deshalb ausdrücklich erlaubt und wird nicht bestraft. Religionsfreiheit, Steuern und Wahlrecht begründen dieses Recht nicht.","region":"de"},{"number":2,"question":"In Deutschland können Eltern bis zum 14. Lebensjahr ihres Kindes entscheiden, ob es in der Schule am …","answers":["Geschichtsunterricht teilnimmt.","Religionsunterricht teilnimmt.","Politikunterricht teilnimmt.","Sprachunterricht teilnimmt."],"correct":1,"explanation":"Das Grundgesetz schützt die Religionsfreiheit. Bis zum 14. Geburtstag entscheiden deshalb die Eltern über die Teilnahme am Religionsunterricht, danach entscheidet das Kind selbst. Geschichte, Politik und Sprachen sind Pflichtfächer.","region":"de"},{"number":3,"question":"Deutschland ist ein Rechtsstaat. Was ist damit gemeint?","answers":["Alle Einwohner / Einwohnerinnen und der Staat müssen sich an die Gesetze halten.","Der Staat muss sich nicht an die Gesetze halten.","Nur Deutsche müssen die Gesetze befolgen.","Die Gerichte machen die Gesetze."],"correct":0,"explanation":"Rechtsstaat bedeutet, dass auch der Staat selbst an Recht und Gesetz gebunden ist, nicht nur die Bürgerinnen und Bürger. Behörden dürfen nur handeln, wenn ein Gesetz sie dazu ermächtigt. Gesetze macht das Parlament, nicht die Gerichte.","region":"de"},{"number":4,"question":"Welches Recht gehört zu den Grundrechten in Deutschland?","answers":["Waffenbesitz","Faustrecht","Meinungsfreiheit","Selbstjustiz"],"correct":2,"explanation":"Die Meinungsfreiheit steht in Artikel 5 des Grundgesetzes und gehört damit zu den Grundrechten. Waffenbesitz, Faustrecht und Selbstjustiz sind keine Grundrechte. Im Gegenteil: Der Staat hat das Gewaltmonopol.","region":"de"},{"number":5,"question":"Wahlen in Deutschland sind frei. Was bedeutet das?","answers":["Man darf Geld annehmen, wenn man dafür einen bestimmten Kandidaten / eine bestimmte Kandidatin wählt.","Der Wähler darf bei der Wahl weder beeinflusst noch zu einer bestimmten Stimmabgabe gezwungen werden und keine Nachteile durch die Wahl haben.","Nur Personen, die noch nie im Gefängnis waren, dürfen wählen.","Alle wahlberechtigten Personen müssen wählen."],"correct":1,"explanation":"Frei heißt: Niemand darf Sie bei der Wahl unter Druck setzen, kaufen oder für Ihre Stimme benachteiligen. Es gibt in Deutschland auch keine Wahlpflicht. Die weiteren Wahlgrundsätze lauten allgemein, unmittelbar, gleich und geheim.","region":"de"},{"number":6,"question":"Wie heißt die deutsche Verfassung?","answers":["Volksgesetz","Bundesgesetz","Deutsches Gesetz","Grundgesetz"],"correct":3,"explanation":"Die deutsche Verfassung heißt Grundgesetz. Der Name wurde 1949 bewusst gewählt, weil man ihn als vorläufig verstand, bis ganz Deutschland wieder vereint wäre. Seit 1990 gilt es für das gesamte Land.","region":"de"},{"number":7,"question":"Welches Recht gehört zu den Grundrechten, die nach der deutschen Verfassung garantiert werden? Das Recht auf …","answers":["Glaubens- und Gewissensfreiheit","Unterhaltung","Arbeit","Wohnung"],"correct":0,"explanation":"Artikel 4 des Grundgesetzes garantiert die Glaubens- und Gewissensfreiheit. Ein Grundrecht auf Arbeit, Wohnung oder Unterhaltung gibt es dagegen nicht, auch wenn der Sozialstaat in diesen Bereichen unterstützt.","region":"de"},{"number":8,"question":"Was steht nicht im Grundgesetz von Deutschland?","answers":["Die Würde des Menschen ist unantastbar.","Alle sollen gleich viel Geld haben.","Jeder Mensch darf seine Meinung sagen.","Alle sind vor dem Gesetz gleich."],"correct":1,"explanation":"Das Grundgesetz garantiert Gleichheit vor dem Gesetz, nicht Gleichheit des Vermögens. Menschenwürde, Meinungsfreiheit und Gleichheit vor dem Gesetz stehen ausdrücklich im Text, eine Pflicht zu gleichem Einkommen nicht.","region":"de"},{"number":9,"question":"Welches Grundrecht gilt in Deutschland nur für Ausländer / Ausländerinnen? Das Grundrecht auf …","answers":["Schutz der Familie","Menschenwürde","Asyl","Meinungsfreiheit"],"correct":2,"explanation":"Das Asylrecht in Artikel 16a gilt nur für politisch Verfolgte aus dem Ausland, also nur für Ausländerinnen und Ausländer. Menschenwürde, Familienschutz und Meinungsfreiheit gelten dagegen für alle Menschen in Deutschland.","region":"de"},{"number":10,"question":"Was ist mit dem deutschen Grundgesetz vereinbar?","answers":["die Prügelstrafe","die Folter","die Todesstrafe","die Geldstrafe"],"correct":3,"explanation":"Die Geldstrafe ist eine übliche und zulässige Strafe. Todesstrafe, Folter und Prügelstrafe sind verboten, weil sie die Menschenwürde aus Artikel 1 verletzen. Die Todesstrafe ist in Artikel 102 ausdrücklich abgeschafft.","region":"de"},{"number":11,"question":"Wie wird die Verfassung der Bundesrepublik Deutschland genannt?","answers":["Grundgesetz","Bundesverfassung","Gesetzbuch","Verfassungsvertrag"],"correct":0,"explanation":"Die Verfassung der Bundesrepublik Deutschland heißt Grundgesetz, abgekürzt GG. Sie trat am 23. Mai 1949 in Kraft. Begriffe wie Bundesverfassung oder Verfassungsvertrag gibt es in Deutschland nicht.","region":"de"},{"number":12,"question":"Eine Partei im Deutschen Bundestag will die Pressefreiheit abschaffen. Ist das möglich?","answers":["Ja, wenn mehr als die Hälfte der Abgeordneten im Bundestag dafür sind.","Ja, aber dazu müssen zwei Drittel der Abgeordneten im Bundestag dafür sein.","Nein, denn die Pressefreiheit ist ein Grundrecht. Sie kann nicht abgeschafft werden.","Nein, denn nur der Bundesrat kann die Pressefreiheit abschaffen."],"correct":2,"explanation":"Die Pressefreiheit ist ein Grundrecht und zusätzlich durch die Ewigkeitsklausel des Grundgesetzes geschützt. Auch eine große Mehrheit im Bundestag kann sie nicht abschaffen. Genau davor sollen die Grundrechte schützen.","region":"de"},{"number":13,"question":"Im Parlament steht der Begriff „Opposition“ für…","answers":["die regierenden Parteien.","alle Abgeordneten, die nicht zu der Regierungspartei/den Regierungsparteien gehören.","die Fraktion mit den meisten Abgeordneten.","alle Parteien, die bei der letzten Wahl die 5%-Hürde erreichen konnten."],"correct":1,"explanation":"Opposition sind alle Abgeordneten, die nicht zu den Regierungsparteien gehören. Ihre wichtigste Aufgabe ist die Kontrolle der Regierung. Die Größe der Fraktion spielt dabei keine Rolle.","region":"de"},{"number":14,"question":"Meinungsfreiheit in Deutschland heißt zum Beispiel, dass ich …","answers":["Passanten auf der Straße beschimpfen darf.","meine Meinung im Internet äußern kann.","Nazi-, Hamas- oder Islamischer Staat-Symbole öffentlich tragen darf.","meine Meinung nur dann äußern darf, solange ich der Regierung nicht widerspreche."],"correct":1,"explanation":"Meinungsfreiheit heißt, dass Sie Ihre Meinung frei äußern dürfen, auch im Internet und auch gegen die Regierung. Sie deckt aber keine Beleidigungen und keine Symbole verbotener Organisationen. Die Grenze zieht das Strafrecht.","region":"de"},{"number":15,"question":"Was verbietet das deutsche Grundgesetz?","answers":["Militärdienst","Zwangsarbeit","freie Berufswahl","Arbeit im Ausland"],"correct":1,"explanation":"Artikel 12 des Grundgesetzes verbietet Zwangsarbeit und garantiert die freie Berufswahl. Militärdienst ist dagegen ausdrücklich zulässig, und Arbeit im Ausland ist erlaubt.","region":"de"},{"number":16,"question":"Wann ist die Meinungsfreiheit in Deutschland eingeschränkt?","answers":["bei der öffentlichen Verbreitung falscher Behauptungen über einzelne Personen","bei Meinungsäußerungen über die Bundesregierung","bei Diskussionen über Religionen","bei Kritik am Staat"],"correct":0,"explanation":"Meinungsfreiheit schützt Meinungen, nicht bewusst falsche Tatsachenbehauptungen über einzelne Personen. Üble Nachrede und Verleumdung sind strafbar. Kritik am Staat, an der Regierung und an Religionen bleibt dagegen erlaubt.","region":"de"},{"number":17,"question":"Die deutschen Gesetze verbieten …","answers":["Meinungsfreiheit der Einwohner und Einwohnerinnen.","Petitionen der Bürger und Bürgerinnen.","Versammlungsfreiheit der Einwohner und Einwohnerinnen.","Ungleichbehandlung der Bürger und Bürgerinnen durch den Staat."],"correct":3,"explanation":"Artikel 3 des Grundgesetzes verbietet dem Staat, Menschen ohne sachlichen Grund ungleich zu behandeln, etwa wegen Herkunft, Geschlecht oder Religion. Meinungs-, Versammlungs- und Petitionsfreiheit sind dagegen ausdrücklich garantiert.","region":"de"},{"number":18,"question":"Welches Grundrecht ist in Artikel 1 des Grundgesetzes der Bundesrepublik Deutschland garantiert?","answers":["die Unantastbarkeit der Menschenwürde","das Recht auf Leben","Religionsfreiheit","Meinungsfreiheit"],"correct":0,"explanation":"Artikel 1 Absatz 1 lautet: Die Würde des Menschen ist unantastbar. Sie steht bewusst an erster Stelle und ist die Grundlage aller weiteren Grundrechte. Das Recht auf Leben folgt erst in Artikel 2.","region":"de"},{"number":19,"question":"Was versteht man unter dem Recht der „Freizügigkeit“ in Deutschland?","answers":["Man darf sich seinen Wohnort selbst aussuchen.","Man kann seinen Beruf wechseln.","Man darf sich für eine andere Religion entscheiden.","Man darf sich in der Öffentlichkeit nur leicht bekleidet bewegen."],"correct":0,"explanation":"Freizügigkeit nach Artikel 11 bedeutet, dass Sie Wohnort und Aufenthaltsort in Deutschland frei wählen dürfen. Die freie Berufswahl steht dagegen in Artikel 12, die Religionsfreiheit in Artikel 4.","region":"de"},{"number":20,"question":"Eine Partei in Deutschland verfolgt das Ziel, eine Diktatur zu errichten. Sie ist dann …","answers":["tolerant.","rechtsstaatlich orientiert.","gesetzestreu.","verfassungswidrig."],"correct":3,"explanation":"Parteien, die die freiheitliche demokratische Grundordnung beseitigen wollen, sind verfassungswidrig. Über ein Verbot entscheidet allein das Bundesverfassungsgericht. Dieses Prinzip nennt man wehrhafte Demokratie.","region":"de"},{"number":21,"question":"Welches ist das Wappen der Bundesrepublik Deutschland?","image":"assets/germany-coat-of-arms.png","answers":["1","2","3","4"],"correct":0,"explanation":"Das Bundeswappen zeigt einen schwarzen Adler auf goldenem Grund, den Bundesadler. Er geht auf den Reichsadler der Weimarer Republik zurück und ist auch im Plenarsaal des Bundestages zu sehen.","region":"de"},{"number":22,"question":"Was für eine Staatsform hat Deutschland?","answers":["Monarchie","Diktatur","Republik","Fürstentum"],"correct":2,"explanation":"Deutschland ist eine Republik: Das Staatsoberhaupt wird gewählt und erbt sein Amt nicht. Die Monarchie endete 1918, die Diktaturen 1945 beziehungsweise 1990.","region":"de"},{"number":23,"question":"In Deutschland sind die meisten Erwerbstätigen …","answers":["bei einer Firma oder Behörde beschäftigt.","in kleinen Familienunternehmen beschäftigt.","ehrenamtlich für ein Bundesland tätig.","selbständig mit einer eigenen Firma tätig."],"correct":0,"explanation":"Rund neun von zehn Erwerbstätigen in Deutschland sind abhängig beschäftigt, also bei einer Firma oder einer Behörde angestellt. Nur etwa jeder zehnte Erwerbstätige ist selbständig.","region":"de"},{"number":24,"question":"Wie viele Bundesländer hat die Bundesrepublik Deutschland?","answers":["14","15","16","17"],"correct":2,"explanation":"Deutschland besteht aus 16 Bundesländern. Bis 1990 waren es elf, mit der Wiedervereinigung kamen die fünf ostdeutschen Länder hinzu.","region":"de"},{"number":25,"question":"Was ist kein Bundesland der Bundesrepublik Deutschland?","answers":["Nordrhein-Westfalen","Elsass-Lothringen","Mecklenburg-Vorpommern","Sachsen-Anhalt"],"correct":1,"explanation":"Elsass-Lothringen liegt in Frankreich und ist kein deutsches Bundesland. Nordrhein-Westfalen, Mecklenburg-Vorpommern und Sachsen-Anhalt gehören dagegen zu den 16 Ländern.","region":"de"},{"number":26,"question":"Deutschland ist …","answers":["eine kommunistische Republik.","ein demokratischer und sozialer Bundesstaat.","eine kapitalistische und soziale Monarchie.","ein sozialer und sozialistischer Bundesstaat."],"correct":1,"explanation":"Artikel 20 des Grundgesetzes beschreibt Deutschland als demokratischen und sozialen Bundesstaat. Diese Formulierung sollten Sie sich merken, sie kommt in mehreren Fragen vor.","region":"de"},{"number":27,"question":"Deutschland ist …","answers":["ein sozialistischer Staat.","ein Bundesstaat.","eine Diktatur.","eine Monarchie."],"correct":1,"explanation":"Deutschland ist ein Bundesstaat: Die Staatsgewalt ist zwischen dem Bund und den 16 Ländern aufgeteilt, und beide Ebenen haben eigene Parlamente und Regierungen.","region":"de"},{"number":28,"question":"Wer wählt in Deutschland die Abgeordneten zum Bundestag?","answers":["das Militär","die Wirtschaft","das wahlberechtigte Volk","die Verwaltung"],"correct":2,"explanation":"Die Abgeordneten des Bundestages werden vom wahlberechtigten Volk gewählt, also von allen deutschen Staatsangehörigen ab 18 Jahren. Militär, Wirtschaft und Verwaltung haben darauf keinen Einfluss.","region":"de"},{"number":29,"question":"Welches Tier ist das Wappentier der Bundesrepublik Deutschland?","answers":["Löwe","Adler","Bär","Pferd"],"correct":1,"explanation":"Das Wappentier Deutschlands ist der Adler. Der Bundesadler ist auf dem Wappen, auf Münzen, auf Ausweisen und im Plenarsaal des Bundestages zu sehen.","region":"de"},{"number":30,"question":"Was ist kein Merkmal unserer Demokratie?","answers":["regelmäßige Wahlen","Pressezensur","Meinungsfreiheit","verschiedene Parteien"],"correct":1,"explanation":"Pressezensur widerspricht der Demokratie, Artikel 5 des Grundgesetzes verbietet sie ausdrücklich. Regelmäßige Wahlen, Meinungsfreiheit und mehrere Parteien sind dagegen Kennzeichen einer Demokratie.","region":"de"},{"number":31,"question":"Die Zusammenarbeit von Parteien zur Bildung einer Regierung nennt man in Deutschland …","answers":["Einheit.","Koalition.","Ministerium.","Fraktion."],"correct":1,"explanation":"Wenn eine Partei allein keine Mehrheit hat, schließt sie sich mit anderen zu einer Koalition zusammen. Eine Fraktion ist dagegen der Zusammenschluss der Abgeordneten einer Partei im Parlament.","region":"de"},{"number":32,"question":"Was ist keine staatliche Gewalt in Deutschland?","answers":["Gesetzgebung","Regierung","Presse","Rechtsprechung"],"correct":2,"explanation":"Die drei Staatsgewalten sind Legislative (Gesetzgebung), Exekutive (Regierung und Verwaltung) und Judikative (Rechtsprechung). Die Presse ist keine Staatsgewalt, sie wird nur umgangssprachlich vierte Gewalt genannt.","region":"de"},{"number":33,"question":"Welche Aussage ist richtig? In Deutschland …","answers":["sind Staat und Religionsgemeinschaften voneinander getrennt.","bilden die Religionsgemeinschaften den Staat.","ist der Staat abhängig von den Religionsgemeinschaften.","bilden Staat und Religionsgemeinschaften eine Einheit."],"correct":0,"explanation":"In Deutschland gilt die weltanschauliche Neutralität des Staates: Staat und Religionsgemeinschaften sind getrennt. Es gibt keine Staatsreligion, wohl aber eine Zusammenarbeit etwa bei Schulen und sozialen Diensten.","region":"de"},{"number":34,"question":"Was ist Deutschland nicht?","answers":["eine Demokratie","ein Rechtsstaat","eine Monarchie","ein Sozialstaat"],"correct":2,"explanation":"Deutschland ist Demokratie, Rechtsstaat, Sozialstaat und Bundesstaat, aber keine Monarchie. Die Monarchie endete in Deutschland 1918.","region":"de"},{"number":35,"question":"Womit finanziert der deutsche Staat die Sozialversicherung?","answers":["Kirchensteuern","Sozialabgaben","Spendengeldern","Vereinsbeiträgen"],"correct":1,"explanation":"Die Sozialversicherung wird über Sozialabgaben finanziert, die Arbeitgeber und Arbeitnehmer gemeinsam vom Bruttolohn zahlen. Kirchensteuern, Spenden und Vereinsbeiträge fließen nicht in die Sozialversicherung.","region":"de"},{"number":36,"question":"Welche Maßnahme schafft in Deutschland soziale Sicherheit?","answers":["die Krankenversicherung","die Autoversicherung","die Gebäudeversicherung","die Haftpflichtversicherung"],"correct":0,"explanation":"Die Krankenversicherung gehört zu den fünf gesetzlichen Sozialversicherungen und schafft soziale Sicherheit. Auto-, Gebäude- und Haftpflichtversicherung sind private Sachversicherungen und schützen Eigentum, nicht Menschen.","region":"de"},{"number":37,"question":"Wie werden die Regierungschefs / Regierungschefinnen der meisten Bundesländer in Deutschland genannt?","answers":["Erster Minister / Erste Ministerin","Premierminister / Premierministerin","Senator / Senatorin","Ministerpräsident / Ministerpräsidentin"],"correct":3,"explanation":"In den 13 Flächenländern heißt der Regierungschef Ministerpräsident oder Ministerpräsidentin. Nur in den Stadtstaaten Berlin, Hamburg und Bremen gibt es andere Amtsbezeichnungen.","region":"de"},{"number":38,"question":"Die Bundesrepublik Deutschland ist ein demokratischer und sozialer …","answers":["Staatenverbund.","Bundesstaat.","Staatenbund.","Zentralstaat."],"correct":1,"explanation":"Ein Bundesstaat besteht aus Gliedstaaten mit eigener Staatlichkeit. Ein Staatenbund ist dagegen nur ein Zusammenschluss selbständiger Staaten, und ein Zentralstaat hätte gar keine eigenständigen Länder.","region":"de"},{"number":39,"question":"Was hat jedes deutsche Bundesland?","answers":["einen eigenen Außenminister / eine eigene Außenministerin","eine eigene Währung","eine eigene Armee","eine eigene Regierung"],"correct":3,"explanation":"Jedes Bundesland hat eine eigene Verfassung, ein eigenes Parlament und eine eigene Regierung. Außenpolitik, Verteidigung und Währung sind dagegen allein Sache des Bundes.","region":"de"},{"number":40,"question":"Mit welchen Worten beginnt die deutsche Nationalhymne?","answers":["Völker, hört die Signale …","Einigkeit und Recht und Freiheit …","Freude schöner Götterfunken …","Deutschland einig Vaterland …"],"correct":1,"explanation":"Die Nationalhymne beginnt mit „Einigkeit und Recht und Freiheit“. Gesungen wird nur die dritte Strophe des Liedes der Deutschen von Hoffmann von Fallersleben.","region":"de"},{"number":41,"question":"Warum gibt es in einer Demokratie mehr als eine Partei?","answers":["weil dadurch die unterschiedlichen Meinungen der Bürger und Bürgerinnen vertreten werden","damit Bestechung in der Politik begrenzt wird","um politische Demonstrationen zu verhindern","um wirtschaftlichen Wettbewerb anzuregen"],"correct":0,"explanation":"In einer Gesellschaft gibt es viele verschiedene Interessen und Meinungen. Mehrere Parteien sorgen dafür, dass diese Vielfalt im Parlament vertreten ist und die Wähler eine echte Auswahl haben.","region":"de"},{"number":42,"question":"Wer beschließt in Deutschland ein neues Gesetz?","answers":["die Regierung","das Parlament","die Gerichte","die Polizei"],"correct":1,"explanation":"Gesetze beschließt das Parlament, also der Bundestag, bei vielen Gesetzen zusammen mit dem Bundesrat. Die Regierung kann Gesetze nur vorschlagen, Gerichte und Polizei wenden sie an.","region":"de"},{"number":43,"question":"Wann kann in Deutschland eine Partei verboten werden?","answers":["wenn ihr Wahlkampf zu teuer ist","wenn sie gegen die Verfassung kämpft","wenn sie Kritik am Staatsoberhaupt äußert","wenn ihr Programm eine neue Richtung vorschlägt"],"correct":1,"explanation":"Eine Partei kann nur verboten werden, wenn sie die freiheitliche demokratische Grundordnung aktiv bekämpft. Über das Verbot entscheidet ausschließlich das Bundesverfassungsgericht. Kritik am Staat allein reicht nie aus.","region":"de"},{"number":44,"question":"Wen kann man als Bürger / Bürgerin in Deutschland nicht direkt wählen?","answers":["Abgeordnete des EU-Parlaments","den Bundespräsidenten / die Bundespräsidentin","Landtagsabgeordnete","Bundestagsabgeordnete"],"correct":1,"explanation":"Den Bundespräsidenten wählt die Bundesversammlung, nicht das Volk. Bundestag, Landtage und das Europäische Parlament werden dagegen direkt gewählt.","region":"de"},{"number":45,"question":"Zu welcher Versicherung gehört die Pflegeversicherung?","answers":["Sozialversicherung","Unfallversicherung","Hausratversicherung","Haftpflicht- und Feuerversicherung"],"correct":0,"explanation":"Die Pflegeversicherung ist seit 1995 die fünfte Säule der gesetzlichen Sozialversicherung, neben Kranken-, Renten-, Arbeitslosen- und Unfallversicherung.","region":"de"},{"number":46,"question":"Der deutsche Staat hat viele Aufgaben. Welche Aufgabe gehört dazu?","answers":["Er baut Straßen und Schulen.","Er verkauft Lebensmittel und Kleidung.","Er versorgt alle Einwohner und Einwohnerinnen kostenlos mit Zeitungen.","Er produziert Autos und Busse."],"correct":0,"explanation":"Der Staat stellt die öffentliche Infrastruktur bereit, also zum Beispiel Straßen, Schulen und Krankenhäuser. Die Produktion von Autos, Lebensmitteln oder Kleidung überlässt er der Privatwirtschaft.","region":"de"},{"number":47,"question":"Der deutsche Staat hat viele Aufgaben. Welche Aufgabe gehört nicht dazu?","answers":["Er bezahlt für alle Staatsangehörigen Urlaubsreisen.","Er zahlt Kindergeld.","Er unterstützt Museen.","Er fördert Sportler und Sportlerinnen."],"correct":0,"explanation":"Urlaubsreisen bezahlt der Staat nicht. Kindergeld, die Förderung von Museen und die Sportförderung gehören dagegen zu seinen Aufgaben.","region":"de"},{"number":48,"question":"Welches Organ gehört nicht zu den Verfassungsorganen Deutschlands?","answers":["der Bundesrat","der Bundespräsident / die Bundespräsidentin","die Bürgerversammlung","die Regierung"],"correct":2,"explanation":"Die fünf Verfassungsorgane des Bundes sind Bundestag, Bundesrat, Bundesregierung, Bundespräsident und Bundesverfassungsgericht. Eine Bürgerversammlung ist kein Verfassungsorgan.","region":"de"},{"number":49,"question":"Wer bestimmt in Deutschland die Schulpolitik?","answers":["die Lehrer und Lehrerinnen","die Bundesländer","das Familienministerium","die Universitäten"],"correct":1,"explanation":"Bildung ist Ländersache. Deshalb entscheidet jedes Bundesland selbst über Lehrpläne, Schulformen und Ferien. Das nennt man Kulturhoheit der Länder.","region":"de"},{"number":50,"question":"Die Wirtschaftsform in Deutschland nennt man …","answers":["freie Zentralwirtschaft.","soziale Marktwirtschaft.","gelenkte Zentralwirtschaft.","Planwirtschaft."],"correct":1,"explanation":"Die deutsche Wirtschaftsordnung heißt soziale Marktwirtschaft. Angebot und Nachfrage bestimmen die Preise, der Staat sorgt aber für sozialen Ausgleich und faire Regeln.","region":"de"},{"number":51,"question":"Zu einem demokratischen Rechtsstaat gehört es nicht, dass …","answers":["Menschen sich kritisch über die Regierung äußern können.","Bürger friedlich demonstrieren gehen dürfen.","Menschen von einer Privatpolizei ohne Grund verhaftet werden.","jemand ein Verbrechen begeht und deshalb verhaftet wird."],"correct":2,"explanation":"In einem Rechtsstaat darf nur der Staat Menschen festnehmen, und auch das nur auf gesetzlicher Grundlage. Eine Privatpolizei, die ohne Grund verhaftet, wäre ein klarer Bruch dieses Prinzips.","region":"de"},{"number":52,"question":"Was bedeutet „Volkssouveränität“? Alle Staatsgewalt geht vom …","answers":["Volke aus.","Bundestag aus.","preußischen König aus.","Bundesverfassungsgericht aus."],"correct":0,"explanation":"Volkssouveränität steht in Artikel 20: Alle Staatsgewalt geht vom Volke aus. Das Volk übt sie durch Wahlen und über die Staatsorgane aus, nicht ein König und nicht ein einzelnes Gericht.","region":"de"},{"number":53,"question":"Was bedeutet „Rechtsstaat“ in Deutschland?","answers":["Der Staat hat Recht.","Es gibt nur rechte Parteien.","Die Bürger und Bürgerinnen entscheiden über Gesetze.","Der Staat muss die Gesetze einhalten."],"correct":3,"explanation":"Rechtsstaat bedeutet, dass der Staat selbst die Gesetze einhalten muss. Der Begriff hat nichts mit rechten Parteien zu tun und bedeutet auch nicht, dass der Staat immer Recht hat.","region":"de"},{"number":54,"question":"Was ist keine staatliche Gewalt in Deutschland?","answers":["Legislative","Judikative","Exekutive","Direktive"],"correct":3,"explanation":"Die drei Staatsgewalten heißen Legislative, Exekutive und Judikative. Eine Direktive gibt es als Staatsgewalt nicht, das Wort bedeutet lediglich Anweisung.","region":"de"},{"number":55,"question":"Was zeigt dieses Bild?","image":"assets/55-berlin-bundestag.png","answers":["den Bundestagssitz in Berlin","das Bundesverfassungsgericht in Karlsruhe","das Bundesratsgebäude in Berlin","das Bundeskanzleramt in Berlin"],"correct":0,"explanation":"Das Bild zeigt das Reichstagsgebäude in Berlin, den Sitz des Deutschen Bundestages. Erkennbar ist es an der gläsernen Kuppel, die 1999 aufgesetzt wurde.","region":"de"},{"number":56,"question":"Welches Amt gehört in Deutschland zur Gemeindeverwaltung?","answers":["Pfarramt","Ordnungsamt","Finanzamt","Auswärtiges Amt"],"correct":1,"explanation":"Das Ordnungsamt gehört zur Gemeindeverwaltung. Das Finanzamt ist eine Landesbehörde, das Auswärtige Amt eine Bundesbehörde und das Pfarramt gehört zur Kirche.","region":"de"},{"number":57,"question":"Wer wird meistens zum Präsidenten / zur Präsidentin des Deutschen Bundestages gewählt?","answers":["der / die älteste Abgeordnete im Parlament","der Ministerpräsident / die Ministerpräsidentin des größten Bundeslandes","ein Abgeordneter / eine Abgeordnete der stärksten Fraktion","ein ehemaliger Bundeskanzler / eine ehemalige Bundeskanzlerin"],"correct":2,"explanation":"Traditionell stellt die stärkste Fraktion den Bundestagspräsidenten oder die Bundestagspräsidentin. Das Amt ist protokollarisch das zweithöchste im Staat, direkt nach dem Bundespräsidenten.","region":"de"},{"number":58,"question":"Wer ernennt in Deutschland die Minister / die Ministerinnen der Bundesregierung?","answers":["der Präsident / die Präsidentin des Bundesverfassungsgerichtes","der Bundespräsident / die Bundespräsidentin","der Bundesratspräsident / die Bundesratspräsidentin","der Bundestagspräsident / die Bundestagspräsidentin"],"correct":1,"explanation":"Der Bundeskanzler schlägt die Ministerinnen und Minister vor, ernannt werden sie aber formal vom Bundespräsidenten. Das gehört zu dessen repräsentativen Aufgaben.","region":"de"},{"number":59,"question":"Vor wie vielen Jahren gab es erstmals eine jüdische Gemeinde auf dem Gebiet des heutigen Deutschlands?","answers":["vor etwa 300 Jahren","vor etwa 700 Jahren","vor etwa 1150 Jahren","vor etwa 1700 Jahren"],"correct":3,"explanation":"Ein Edikt Kaiser Konstantins aus dem Jahr 321 belegt eine jüdische Gemeinde in Köln. Jüdisches Leben in Deutschland ist damit rund 1700 Jahre alt, was 2021 bundesweit gefeiert wurde.","region":"de"},{"number":60,"question":"In Deutschland gehören der Bundestag und der Bundesrat zur …","answers":["Exekutive.","Legislative.","Direktive.","Judikative."],"correct":1,"explanation":"Bundestag und Bundesrat machen Gesetze und gehören deshalb zur Legislative. Die Bundesregierung gehört zur Exekutive, die Gerichte zur Judikative.","region":"de"},{"number":61,"question":"Was bedeutet „Volkssouveränität“?","answers":["Der König / die Königin herrscht über das Volk.","Das Bundesverfassungsgericht steht über der Verfassung.","Die Interessenverbände üben die Souveränität zusammen mit der Regierung aus.","Die Staatsgewalt geht vom Volke aus."],"correct":3,"explanation":"Volkssouveränität heißt: Die Staatsgewalt geht vom Volke aus. Nicht ein Monarch, ein Gericht oder ein Verband, sondern die Wählerinnen und Wähler sind die Quelle aller staatlichen Macht.","region":"de"},{"number":62,"question":"Wenn das Parlament eines deutschen Bundeslandes gewählt wird, nennt man das …","answers":["Kommunalwahl.","Landtagswahl.","Europawahl.","Bundestagswahl."],"correct":1,"explanation":"Die Wahl eines Landesparlaments heißt Landtagswahl. Kommunalwahl meint Gemeinde- und Kreisebene, Bundestagswahl den Bund und Europawahl das Europäische Parlament.","region":"de"},{"number":63,"question":"Was gehört in Deutschland nicht zur Exekutive?","answers":["die Polizei","die Gerichte","das Finanzamt","die Ministerien"],"correct":1,"explanation":"Die Gerichte gehören zur Judikative, nicht zur Exekutive. Polizei, Finanzamt und Ministerien führen dagegen Gesetze aus und gehören damit zur vollziehenden Gewalt.","region":"de"},{"number":64,"question":"Die Bundesrepublik Deutschland ist heute gegliedert in …","answers":["vier Besatzungszonen.","einen Oststaat und einen Weststaat.","16 Kantone.","Bund, Länder und Kommunen."],"correct":3,"explanation":"Deutschland ist dreistufig aufgebaut: Bund, Länder und Kommunen. Besatzungszonen gab es nur von 1945 bis 1949, Kantone gibt es in der Schweiz.","region":"de"},{"number":65,"question":"Es gehört nicht zu den Aufgaben des Deutschen Bundestages, …","answers":["Gesetze zu entwerfen.","die Bundesregierung zu kontrollieren.","den Bundeskanzler / die Bundeskanzlerin zu wählen.","das Bundeskabinett zu bilden."],"correct":3,"explanation":"Der Bundestag entwirft Gesetze, kontrolliert die Regierung und wählt den Bundeskanzler. Das Kabinett bildet dagegen der Kanzler selbst, indem er die Ministerinnen und Minister vorschlägt.","region":"de"},{"number":66,"question":"Welche Städte haben die größten jüdischen Gemeinden in Deutschland?","answers":["Berlin und München","Hamburg und Essen","Nürnberg und Stuttgart","Worms und Speyer"],"correct":0,"explanation":"Die größten jüdischen Gemeinden Deutschlands bestehen heute in Berlin und München. Worms und Speyer sind zwar historisch bedeutende Zentren, haben heute aber nur kleine Gemeinden.","region":"de"},{"number":67,"question":"Was ist in Deutschland vor allem eine Aufgabe der Bundesländer?","answers":["Verteidigungspolitik","Außenpolitik","Wirtschaftspolitik","Schulpolitik"],"correct":3,"explanation":"Schulpolitik ist Aufgabe der Bundesländer. Verteidigung, Außenpolitik und die großen Linien der Wirtschaftspolitik liegen dagegen beim Bund.","region":"de"},{"number":68,"question":"Warum kontrolliert der Staat in Deutschland das Schulwesen?","answers":["weil es in Deutschland nur staatliche Schulen gibt","weil alle Schüler und Schülerinnen einen Schulabschluss haben müssen","weil es in den Bundesländern verschiedene Schulen gibt","weil es nach dem Grundgesetz seine Aufgabe ist"],"correct":3,"explanation":"Artikel 7 des Grundgesetzes stellt das gesamte Schulwesen unter die Aufsicht des Staates. Das gilt auch für Privatschulen, die deshalb genehmigt und beaufsichtigt werden.","region":"de"},{"number":69,"question":"Die Bundesrepublik Deutschland hat einen dreistufigen Verwaltungsaufbau. Wie heißt die unterste politische Stufe?","answers":["Stadträte","Landräte","Gemeinden","Bezirksämter"],"correct":2,"explanation":"Die unterste politische Ebene sind die Gemeinden, also Städte und Dörfer mit eigenem Rat und eigenem Bürgermeister. Darüber liegen die Länder und der Bund.","region":"de"},{"number":70,"question":"Der deutsche Bundespräsident Gustav Heinemann gibt Helmut Schmidt 1974 die Ernennungsurkunde zum deutschen Bundeskanzler. Was gehört zu den Aufgaben des deutschen Bundespräsidenten / der deutschen Bundespräsidentin?","image":"assets/70-budespraesident.png","answers":["Er / Sie führt die Regierungsgeschäfte.","Er / Sie kontrolliert die Regierungspartei.","Er / Sie wählt die Minister / Ministerinnen aus.","Er / Sie schlägt den Kanzler / die Kanzlerin zur Wahl vor."],"correct":3,"explanation":"Der Bundespräsident schlägt dem Bundestag den Kanzlerkandidaten zur Wahl vor und ernennt danach die Regierung. Er regiert selbst nicht und wählt die Ministerinnen und Minister auch nicht aus.","region":"de"},{"number":71,"question":"Wo hält sich der deutsche Bundeskanzler / die deutsche Bundeskanzlerin am häufigsten auf? Am häufigsten ist er / sie …","answers":["in Bonn, weil sich dort das Bundeskanzleramt und der Bundestag befinden.","in Berlin, weil sich dort das Bundeskanzleramt und der Bundestag befinden.","auf Schloss Meseberg, dem Gästehaus der Bundesregierung, um Staatsgäste zu empfangen.","auf Schloss Bellevue, dem Amtssitz des Bundespräsidenten / der Bundespräsidentin, um Staatsgäste zu empfangen."],"correct":1,"explanation":"Seit dem Umzug von Bonn nach Berlin 1999 arbeiten Bundeskanzleramt und Bundestag in Berlin. Schloss Bellevue ist der Sitz des Bundespräsidenten, Meseberg nur ein Gästehaus.","region":"de"},{"number":72,"question":"Wie heißt der jetzige Bundeskanzler / die jetzige Bundeskanzlerin von Deutschland?","answers":["Gerhard Schröder","Angela Merkel","Franziska Giffey","Olaf Scholz"],"correct":3,"explanation":"Der amtliche Fragenkatalog des BAMF nennt hier Olaf Scholz. Markieren Sie in der Prüfung immer die Antwort, die im aktuellen Katalog vorgesehen ist.","region":"de"},{"number":73,"question":"Die beiden größten Fraktionen im Deutschen Bundestag heißen zurzeit …","answers":["CDU/CSU und SPD.","Die Linke und Bündnis 90/Die Grünen.","FDP und SPD.","Die Linke und FDP."],"correct":0,"explanation":"Der amtliche Fragenkatalog des BAMF nennt hier CDU/CSU und SPD. Markieren Sie in der Prüfung die im aktuellen Katalog vorgesehene Antwort.","region":"de"},{"number":74,"question":"Wie heißt das Parlament für ganz Deutschland?","answers":["Bundesversammlung","Volkskammer","Bundestag","Bundesgerichtshof"],"correct":2,"explanation":"Das Parlament für ganz Deutschland heißt Bundestag. Die Bundesversammlung tritt nur zur Wahl des Bundespräsidenten zusammen, die Volkskammer war das Parlament der DDR.","region":"de"},{"number":75,"question":"Wie heißt Deutschlands heutiges Staatsoberhaupt?","answers":["Frank-Walter Steinmeier","Bärbel Bas","Bodo Ramelow","Joachim Gauck"],"correct":0,"explanation":"Staatsoberhaupt ist der Bundespräsident Frank-Walter Steinmeier, im Amt seit 2017 und 2022 wiedergewählt. Der Bundeskanzler leitet dagegen die Regierung.","region":"de"},{"number":76,"question":"Was bedeutet die Abkürzung CDU in Deutschland?","answers":["Christliche Deutsche Union","Club Deutscher Unternehmer","Christlicher Deutscher Umweltschutz","Christlich Demokratische Union"],"correct":3,"explanation":"CDU steht für Christlich Demokratische Union. Sie wurde 1945 gegründet und bildet im Bundestag zusammen mit der bayerischen CSU eine gemeinsame Fraktion.","region":"de"},{"number":77,"question":"Was ist die Bundeswehr?","answers":["die deutsche Polizei","ein deutscher Hafen","eine deutsche Bürgerinitiative","die deutsche Armee"],"correct":3,"explanation":"Die Bundeswehr ist die Armee der Bundesrepublik Deutschland, gegründet 1955. Sie untersteht im Frieden dem Verteidigungsministerium und wird vom Bundestag kontrolliert.","region":"de"},{"number":78,"question":"Was bedeutet die Abkürzung SPD?","answers":["Sozialistische Partei Deutschlands","Sozialpolitische Partei Deutschlands","Sozialdemokratische Partei Deutschlands","Sozialgerechte Partei Deutschlands"],"correct":2,"explanation":"SPD steht für Sozialdemokratische Partei Deutschlands. Sie wurde 1863 gegründet und ist damit die älteste noch bestehende Partei Deutschlands.","region":"de"},{"number":79,"question":"Was bedeutet die Abkürzung FDP in Deutschland?","answers":["Friedliche Demonstrative Partei","Freie Deutschland Partei","Führende Demokratische Partei","Freie Demokratische Partei"],"correct":3,"explanation":"FDP steht für Freie Demokratische Partei. Sie versteht sich als liberale Partei und wurde 1948 gegründet.","region":"de"},{"number":80,"question":"Welches Gericht in Deutschland ist zuständig für die Auslegung des Grundgesetzes?","answers":["Oberlandesgericht","Amtsgericht","Bundesverfassungsgericht","Verwaltungsgericht"],"correct":2,"explanation":"Das Bundesverfassungsgericht in Karlsruhe legt das Grundgesetz aus und kann Gesetze für nichtig erklären. Amts-, Verwaltungs- und Oberlandesgerichte entscheiden dagegen über Einzelfälle.","region":"de"},{"number":81,"question":"Wer wählt den Bundeskanzler / die Bundeskanzlerin in Deutschland?","answers":["der Bundesrat","die Bundesversammlung","das Volk","der Bundestag"],"correct":3,"explanation":"Der Bundestag wählt den Bundeskanzler, und zwar auf Vorschlag des Bundespräsidenten. Das Volk wählt den Kanzler nicht direkt, sondern nur den Bundestag.","region":"de"},{"number":82,"question":"Wer leitet das deutsche Bundeskabinett?","answers":["der Bundestagspräsident / die Bundestagspräsidentin","der Bundespräsident / die Bundespräsidentin","der Bundeskanzler / die Bundeskanzlerin","der Bundesratspräsident / die Bundesratspräsidentin"],"correct":2,"explanation":"Der Bundeskanzler leitet das Kabinett und bestimmt die Richtlinien der Politik. Das nennt man Richtlinienkompetenz und steht in Artikel 65 des Grundgesetzes.","region":"de"},{"number":83,"question":"Wer wählt den deutschen Bundeskanzler / die deutsche Bundeskanzlerin?","answers":["das Volk","die Bundesversammlung","der Bundestag","die Bundesregierung"],"correct":2,"explanation":"Gewählt wird der Bundeskanzler vom Bundestag. Die Bundesversammlung wählt dagegen den Bundespräsidenten, das Volk wählt nur die Abgeordneten.","region":"de"},{"number":84,"question":"Welche Hauptaufgabe hat der deutsche Bundespräsident / die deutsche Bundespräsidentin? Er / Sie …","answers":["regiert das Land.","entwirft die Gesetze.","repräsentiert das Land.","überwacht die Einhaltung der Gesetze."],"correct":2,"explanation":"Der Bundespräsident repräsentiert Deutschland nach innen und außen, unterzeichnet Gesetze und ernennt die Regierung. Regiert wird das Land dagegen vom Bundeskanzler.","region":"de"},{"number":85,"question":"Wer bildet den deutschen Bundesrat?","answers":["die Abgeordneten des Bundestages","die Minister und Ministerinnen der Bundesregierung","die Regierungsvertreter der Bundesländer","die Parteimitglieder"],"correct":2,"explanation":"Im Bundesrat sitzen Mitglieder der Landesregierungen, nicht gewählte Abgeordnete. Über den Bundesrat wirken die 16 Länder an der Gesetzgebung des Bundes mit.","region":"de"},{"number":86,"question":"Wer wählt in Deutschland den Bundespräsidenten / die Bundespräsidentin?","answers":["die Bundesversammlung","der Bundesrat","das Bundesparlament","das Bundesverfassungsgericht"],"correct":0,"explanation":"Der Bundespräsident wird von der Bundesversammlung gewählt. Sie besteht aus allen Bundestagsabgeordneten und ebenso vielen Mitgliedern, die von den Landesparlamenten bestimmt werden.","region":"de"},{"number":87,"question":"Wer ist das Staatsoberhaupt der Bundesrepublik Deutschland?","answers":["der Bundeskanzler / die Bundeskanzlerin","der Bundespräsident / die Bundespräsidentin","der Bundesratspräsident / die Bundesratspräsidentin","der Bundestagspräsident / die Bundestagspräsidentin"],"correct":1,"explanation":"Staatsoberhaupt ist der Bundespräsident oder die Bundespräsidentin. Der Kanzler führt die Regierungsgeschäfte, ist aber nicht Staatsoberhaupt.","region":"de"},{"number":88,"question":"Die parlamentarische Opposition im Deutschen Bundestag …","answers":["kontrolliert die Regierung.","entscheidet, wer Bundesminister / Bundesministerin wird.","bestimmt, wer im Bundesrat sitzt.","schlägt die Regierungschefs / Regierungschefinnen der Länder vor."],"correct":0,"explanation":"Die wichtigste Aufgabe der Opposition ist die Kontrolle der Regierung, etwa durch Anfragen, Debatten und Untersuchungsausschüsse. Über Ministerposten oder den Bundesrat entscheidet sie nicht.","region":"de"},{"number":89,"question":"Wie nennt man in Deutschland die Vereinigung von Abgeordneten einer Partei im Parlament?","answers":["Verband","Ältestenrat","Fraktion","Opposition"],"correct":2,"explanation":"Der Zusammenschluss der Abgeordneten einer Partei im Parlament heißt Fraktion. Fraktionen erhalten Rederechte, Ausschusssitze und eigene Mittel.","region":"de"},{"number":90,"question":"Die deutschen Bundesländer wirken an der Gesetzgebung des Bundes mit durch …","answers":["den Bundesrat.","die Bundesversammlung.","den Bundestag.","die Bundesregierung."],"correct":0,"explanation":"Über den Bundesrat wirken die Länder an der Gesetzgebung des Bundes mit. Bei Gesetzen, die Länderinteressen berühren, kann er ein Gesetz sogar ganz verhindern.","region":"de"},{"number":91,"question":"In Deutschland kann ein Regierungswechsel in einem Bundesland Auswirkungen auf die Bundespolitik haben. Das Regieren wird …","answers":["schwieriger, wenn sich dadurch die Mehrheit im Bundestag ändert.","leichter, wenn dadurch neue Parteien in den Bundesrat kommen.","schwieriger, wenn dadurch die Mehrheit im Bundesrat verändert wird.","leichter, wenn es sich um ein reiches Bundesland handelt."],"correct":2,"explanation":"Landtagswahlen verändern die Landesregierungen und damit die Stimmen im Bundesrat. Verliert die Bundesregierung dort ihre Mehrheit, wird das Regieren deutlich schwieriger.","region":"de"},{"number":92,"question":"Was bedeutet die Abkürzung CSU in Deutschland?","answers":["Christlich Sichere Union","Christlich Süddeutsche Union","Christlich Sozialer Unternehmerverband","Christlich Soziale Union"],"correct":3,"explanation":"CSU steht für Christlich Soziale Union. Sie tritt nur in Bayern an und bildet im Bundestag mit der CDU eine gemeinsame Fraktion.","region":"de"},{"number":93,"question":"Je mehr „Zweitstimmen“ eine Partei bei einer Bundestagswahl bekommt, desto …","answers":["mehr Sitze erhält die Partei im Parlament.","weniger Erststimmen kann sie haben.","mehr Direktkandidaten der Partei ziehen ins Parlament ein.","größer ist das Risiko, eine Koalition bilden zu müssen."],"correct":0,"explanation":"Die Zweitstimme entscheidet über den Anteil der Sitze einer Partei im Bundestag. Die Erststimme wählt dagegen einen Direktkandidaten im Wahlkreis.","region":"de"},{"number":94,"question":"Ab welchem Alter darf man in Deutschland an der Wahl zum Deutschen Bundestag teilnehmen?","answers":["16","18","21","23"],"correct":1,"explanation":"Bei Bundestagswahlen darf man ab 18 Jahren wählen. Bei Kommunal- und teilweise Landtagswahlen liegt das Wahlalter in mehreren Bundesländern bei 16 Jahren.","region":"de"},{"number":95,"question":"Was gilt für die meisten Kinder in Deutschland?","answers":["Wahlpflicht","Schulpflicht","Schweigepflicht","Religionspflicht"],"correct":1,"explanation":"In Deutschland gilt Schulpflicht, meist von der Einschulung bis mindestens zum 9. oder 10. Schuljahr. Eine Wahlpflicht oder Religionspflicht gibt es nicht.","region":"de"},{"number":96,"question":"Wie kann jemand, der den Holocaust leugnet, bestraft werden?","answers":["Kürzung sozialer Leistungen","bis zu 100 Sozialstunden","gar nicht, Holocaustleugnung ist erlaubt","mit Freiheitsstrafe bis zu fünf Jahren oder mit Geldstrafe"],"correct":3,"explanation":"Die Leugnung des Holocaust ist nach Paragraf 130 des Strafgesetzbuchs Volksverhetzung. Sie wird mit Freiheitsstrafe bis zu fünf Jahren oder mit Geldstrafe bestraft.","region":"de"},{"number":97,"question":"Was bezahlt man in Deutschland automatisch, wenn man fest angestellt ist?","answers":["Sozialversicherung","Sozialhilfe","Kindergeld","Wohngeld"],"correct":0,"explanation":"Bei einer Festanstellung werden die Beiträge zur Sozialversicherung automatisch vom Bruttolohn abgezogen. Kindergeld und Wohngeld muss man dagegen selbst beantragen.","region":"de"},{"number":98,"question":"Wenn Abgeordnete im Deutschen Bundestag ihre Fraktion wechseln, ...","answers":["kann die Regierung ihre Mehrheit verlieren.","dürfen sie nicht mehr an den Sitzungen des Parlaments teilnehmen.","muss der Bundespräsident / die Bundespräsidentin zuvor sein / ihr Einverständnis geben.","dürfen die Wähler / Wählerinnen dieser Abgeordneten noch einmal wählen."],"correct":0,"explanation":"Abgeordnete sind nur ihrem Gewissen verpflichtet und dürfen die Fraktion wechseln. Wenn genug Abgeordnete wechseln, kann die Regierung dadurch ihre Mehrheit verlieren.","region":"de"},{"number":99,"question":"Wer bezahlt in Deutschland die Sozialversicherungen?","answers":["Arbeitgeber / Arbeitgeberinnen und Arbeitnehmer / Arbeitnehmerinnen","nur Arbeitnehmer / Arbeitnehmerinnen","alle Staatsangehörigen","nur Arbeitgeber / Arbeitgeberinnen"],"correct":0,"explanation":"Die Beiträge zur Sozialversicherung teilen sich Arbeitgeber und Arbeitnehmer in der Regel zu gleichen Teilen. Man spricht deshalb von paritätischer Finanzierung.","region":"de"},{"number":100,"question":"Was gehört nicht zur gesetzlichen Sozialversicherung?","answers":["die gesetzliche Rentenversicherung","die Lebensversicherung","die Arbeitslosenversicherung","die Pflegeversicherung"],"correct":1,"explanation":"Die fünf gesetzlichen Sozialversicherungen sind Kranken-, Renten-, Arbeitslosen-, Pflege- und Unfallversicherung. Die Lebensversicherung ist dagegen eine freiwillige private Vorsorge.","region":"de"},{"number":101,"question":"Gewerkschaften sind Interessenverbände der …","answers":["Jugendlichen.","Arbeitnehmer und Arbeitnehmerinnen.","Rentner und Rentnerinnen.","Arbeitgeber und Arbeitgeberinnen."],"correct":1,"explanation":"Gewerkschaften vertreten die Interessen der Arbeitnehmerinnen und Arbeitnehmer, zum Beispiel bei Tarifverhandlungen über Löhne und Arbeitszeiten. Arbeitgeber haben mit den Arbeitgeberverbänden eigene Organisationen.","region":"de"},{"number":102,"question":"Womit kann man in der Bundesrepublik Deutschland geehrt werden, wenn man auf politischem, wirtschaftlichem, kulturellem, geistigem oder sozialem Gebiet eine besondere Leistung erbracht hat? Mit dem …","answers":["Bundesadler","Bundesverdienstkreuz","Vaterländischen Verdienstorden","Ehrentitel „Held der Deutschen Demokratischen Republik“"],"correct":1,"explanation":"Das Bundesverdienstkreuz ist der einzige allgemeine Verdienstorden der Bundesrepublik. Verliehen wird es vom Bundespräsidenten für besondere Leistungen um das Gemeinwohl.","region":"de"},{"number":103,"question":"Was wird in Deutschland als „Ampelkoalition“ bezeichnet? Die Zusammenarbeit …","answers":["der Bundestagsfraktionen von CDU und CSU","von SPD, FDP und Bündnis 90/Die Grünen in einer Regierung","von CSU, Die LINKE und Bündnis 90/Die Grünen in einer Regierung","der Bundestagsfraktionen von CDU und SPD"],"correct":1,"explanation":"Ampelkoalition nennt man die Zusammenarbeit von SPD, FDP und Bündnis 90/Die Grünen, weil deren Parteifarben Rot, Gelb und Grün den Farben einer Ampel entsprechen. Solche Farbnamen gibt es auch für andere Bündnisse, etwa Große Koalition oder Jamaika.","region":"de"},{"number":104,"question":"Eine Frau in Deutschland verliert ihre Arbeit. Was darf nicht der Grund für diese Entlassung sein?","answers":["Die Frau ist lange krank und arbeitsunfähig.","Die Frau kam oft zu spät zur Arbeit.","Die Frau erledigt private Sachen während der Arbeitszeit.","Die Frau bekommt ein Kind und ihr Chef weiß das."],"correct":3,"explanation":"Während der Schwangerschaft und einige Monate nach der Geburt gilt ein besonderer Kündigungsschutz. Eine Kündigung wegen einer Schwangerschaft ist deshalb unzulässig.","region":"de"},{"number":105,"question":"Was ist eine Aufgabe von Wahlhelfern / Wahlhelferinnen in Deutschland?","answers":["Sie helfen alten Menschen bei der Stimmabgabe in der Wahlkabine.","Sie schreiben die Wahlbenachrichtigungen vor der Wahl.","Sie geben Zwischenergebnisse an die Medien weiter.","Sie zählen die Stimmen nach dem Ende der Wahl."],"correct":3,"explanation":"Wahlhelferinnen und Wahlhelfer sorgen für den ordnungsgemäßen Ablauf im Wahllokal und zählen nach Schließung die Stimmen aus. Sie dürfen niemanden beeinflussen und keine Zwischenergebnisse weitergeben.","region":"de"},{"number":106,"question":"In Deutschland helfen ehrenamtliche Wahlhelfer und Wahlhelferinnen bei den Wahlen. Was ist eine Aufgabe von Wahlhelfern / Wahlhelferinnen?","answers":["Sie helfen Kindern und alten Menschen beim Wählen.","Sie schreiben Karten und Briefe mit der Angabe des Wahllokals.","Sie geben Zwischenergebnisse an Journalisten weiter.","Sie zählen die Stimmen nach dem Ende der Wahl."],"correct":3,"explanation":"Die zentrale Aufgabe der ehrenamtlichen Wahlhelfer ist die Auszählung der Stimmen nach Schließung des Wahllokals. Die Wahlbenachrichtigungen verschickt dagegen die Gemeinde.","region":"de"},{"number":107,"question":"Für wie viele Jahre wird der Bundestag in Deutschland gewählt?","answers":["2 Jahre","4 Jahre","6 Jahre","8 Jahre"],"correct":1,"explanation":"Der Bundestag wird für vier Jahre gewählt. Diese Zeit nennt man Legislaturperiode oder Wahlperiode.","region":"de"},{"number":108,"question":"Bei einer Bundestagswahl in Deutschland darf jeder wählen, der …","answers":["in der Bundesrepublik Deutschland wohnt und wählen möchte.","Bürger / Bürgerin der Bundesrepublik Deutschland ist und mindestens 18 Jahre alt ist.","seit mindestens 3 Jahren in der Bundesrepublik Deutschland lebt.","Bürger / Bürgerin der Bundesrepublik Deutschland ist und mindestens 21 Jahre alt ist."],"correct":1,"explanation":"Wahlberechtigt ist, wer die deutsche Staatsangehörigkeit besitzt und mindestens 18 Jahre alt ist. Wohnsitz allein oder eine bestimmte Aufenthaltsdauer reichen nicht aus.","region":"de"},{"number":109,"question":"Wie oft gibt es normalerweise Bundestagswahlen in Deutschland?","answers":["alle drei Jahre","alle vier Jahre","alle fünf Jahre","alle sechs Jahre"],"correct":1,"explanation":"Bundestagswahlen finden normalerweise alle vier Jahre statt. Nur bei einer vorzeitigen Auflösung des Bundestages wird früher gewählt.","region":"de"},{"number":110,"question":"Für wie viele Jahre wird der Bundestag in Deutschland gewählt?","answers":["2 Jahre","3 Jahre","4 Jahre","5 Jahre"],"correct":2,"explanation":"Die Wahlperiode des Bundestages dauert vier Jahre. Landtage werden dagegen in den meisten Bundesländern für fünf Jahre gewählt.","region":"de"},{"number":111,"question":"Welche Handlung mit Bezug auf den Staat Israel ist in Deutschland verboten?","answers":["Die Politik Israels öffentlich kritisieren.","Das Aufhängen einer israelischen Flagge auf dem Privatgrundstück.","Eine Diskussion über die Politik Israels.","Der öffentliche Aufruf zur Vernichtung Israels."],"correct":3,"explanation":"Der öffentliche Aufruf zur Vernichtung Israels ist strafbar, etwa als Volksverhetzung oder Aufruf zu Straftaten. Kritik an der israelischen Regierung ist dagegen von der Meinungsfreiheit gedeckt und erlaubt.","region":"de"},{"number":112,"question":"Die Wahlen in Deutschland sind …","answers":["speziell.","geheim.","berufsbezogen.","geschlechtsabhängig."],"correct":1,"explanation":"Geheim heißt: Niemand darf erfahren, wie Sie gewählt haben. Deshalb gibt es Wahlkabinen und blickdichte Umschläge. Die fünf Wahlgrundsätze lauten allgemein, unmittelbar, frei, gleich und geheim.","region":"de"},{"number":113,"question":"Wahlen in Deutschland gewinnt die Partei, die …","answers":["die meisten Stimmen bekommt.","die meisten Männer mehrheitlich gewählt haben.","die meisten Stimmen bei den Arbeitern / Arbeiterinnen bekommen hat.","die meisten Erststimmen für ihren Kanzlerkandidaten / ihre Kanzlerkandidatin erhalten hat."],"correct":0,"explanation":"Gewonnen hat die Partei mit den meisten Stimmen. Wer regiert, hängt aber davon ab, wer eine Mehrheit im Bundestag organisieren kann, also von der Koalitionsbildung.","region":"de"},{"number":114,"question":"An demokratischen Wahlen in Deutschland teilzunehmen ist …","answers":["eine Pflicht.","ein Recht.","ein Zwang.","eine Last."],"correct":1,"explanation":"Wählen ist in Deutschland ein Recht, keine Pflicht. Es gibt keine Wahlpflicht und niemand wird bestraft, wenn er nicht zur Wahl geht.","region":"de"},{"number":115,"question":"Was bedeutet „aktives Wahlrecht“ in Deutschland?","answers":["Man kann gewählt werden.","Man muss wählen gehen.","Man kann wählen.","Man muss zur Auszählung der Stimmen gehen."],"correct":2,"explanation":"Aktives Wahlrecht bedeutet, selbst wählen zu dürfen. Passives Wahlrecht bedeutet dagegen, selbst gewählt werden zu können.","region":"de"},{"number":116,"question":"Wenn Sie bei einer Bundestagswahl in Deutschland wählen dürfen, heißt das …","answers":["aktive Wahlkampagne.","aktives Wahlverfahren.","aktiver Wahlkampf.","aktives Wahlrecht."],"correct":3,"explanation":"Das Recht, selbst zu wählen, heißt aktives Wahlrecht. Merken Sie sich: aktiv gleich Stimme abgeben, passiv gleich kandidieren.","region":"de"},{"number":117,"question":"Wie viel Prozent der Zweitstimmen müssen Parteien mindestens bekommen, um in den Deutschen Bundestag gewählt zu werden?","answers":["3 %","4 %","5 %","6 %"],"correct":2,"explanation":"Die Sperrklausel liegt bei fünf Prozent der Zweitstimmen. Parteien darunter ziehen nicht in den Bundestag ein, außer sie gewinnen genug Direktmandate.","region":"de"},{"number":118,"question":"Wer darf bei den rund 40 jüdischen Makkabi-Sportvereinen Mitglied werden?","answers":["nur Deutsche","nur Israelis","nur religiöse Menschen","alle Menschen"],"correct":3,"explanation":"Die jüdischen Makkabi-Sportvereine stehen allen Menschen offen, unabhängig von Religion oder Herkunft. Makkabi Deutschland hat rund 40 Vereine und mehrere tausend Mitglieder.","region":"de"},{"number":119,"question":"Wahlen in Deutschland sind frei. Was bedeutet das?","answers":["Alle verurteilten Straftäter / Straftäterinnen dürfen nicht wählen.","Wenn ich wählen gehen möchte, muss mein Arbeitgeber / meine Arbeitgeberin mir frei geben.","Jede Person kann ohne Zwang entscheiden, ob sie wählen möchte und wen sie wählen möchte.","Ich kann frei entscheiden, wo ich wählen gehen möchte."],"correct":2,"explanation":"Frei bedeutet, dass jede Person ohne Zwang entscheidet, ob und wen sie wählt. Weder Staat noch Arbeitgeber noch Familie dürfen darauf Einfluss nehmen.","region":"de"},{"number":120,"question":"Das Wahlsystem in Deutschland ist ein …","answers":["Zensuswahlrecht.","Dreiklassenwahlrecht.","Mehrheits- und Verhältniswahlrecht.","allgemeines Männerwahlrecht."],"correct":2,"explanation":"Deutschland hat ein Mehrheits- und Verhältniswahlrecht: Mit der Erststimme wird ein Direktkandidat nach Mehrheit gewählt, die Zweitstimme verteilt die Sitze nach dem Verhältnis der Stimmen.","region":"de"},{"number":121,"question":"Eine Partei möchte in den Deutschen Bundestag. Sie muss aber einen Mindestanteil an Wählerstimmen haben. Das heißt …","answers":["5 %-Hürde.","Zulassungsgrenze.","Basiswert.","Richtlinie."],"correct":0,"explanation":"Die Sperrklausel von fünf Prozent heißt in Deutschland Fünf-Prozent-Hürde. Sie soll eine Zersplitterung des Parlaments verhindern.","region":"de"},{"number":122,"question":"Welchem Grundsatz unterliegen Wahlen in Deutschland? Wahlen in Deutschland sind …","answers":["frei, gleich, geheim.","offen, sicher, frei.","geschlossen, gleich, sicher.","sicher, offen, freiwillig."],"correct":0,"explanation":"Die Wahlgrundsätze aus Artikel 38 des Grundgesetzes lauten allgemein, unmittelbar, frei, gleich und geheim. Von den Antwortmöglichkeiten trifft nur frei, gleich, geheim zu.","region":"de"},{"number":123,"question":"Was ist in Deutschland die „5 %-Hürde“?","answers":["Abstimmungsregelung im Bundestag für kleine Parteien","Anwesenheitskontrolle im Bundestag für Abstimmungen","Mindestanteil an Wählerstimmen, um ins Parlament zu kommen","Anwesenheitskontrolle im Bundesrat für Abstimmungen"],"correct":2,"explanation":"Die Fünf-Prozent-Hürde ist der Mindestanteil an Zweitstimmen, den eine Partei für den Einzug ins Parlament braucht. Mit Abstimmungen oder Anwesenheit im Bundestag hat sie nichts zu tun.","region":"de"},{"number":124,"question":"Die Bundestagswahl in Deutschland ist die Wahl …","answers":["des Bundeskanzlers / der Bundeskanzlerin.","der Parlamente der Länder.","des Parlaments für Deutschland.","des Bundespräsidenten / der Bundespräsidentin."],"correct":2,"explanation":"Bei der Bundestagswahl wählen Sie das Parlament, nicht den Kanzler. Den Kanzler wählt anschließend der neu gewählte Bundestag.","region":"de"},{"number":125,"question":"In einer Demokratie ist eine Funktion von regelmäßigen Wahlen, …","answers":["die Bürger und Bürgerinnen zu zwingen, ihre Stimme abzugeben.","nach dem Willen der Wählermehrheit den Wechsel der Regierung zu ermöglichen.","im Land bestehende Gesetze beizubehalten.","den Armen mehr Macht zu geben."],"correct":1,"explanation":"Regelmäßige Wahlen ermöglichen einen friedlichen Machtwechsel: Die Mehrheit kann eine Regierung abwählen und eine andere einsetzen. Das unterscheidet Demokratien von Diktaturen.","region":"de"},{"number":126,"question":"Was bekommen wahlberechtigte Bürger und Bürgerinnen in Deutschland vor einer Wahl?","answers":["eine Wahlbenachrichtigung von der Gemeinde","eine Wahlerlaubnis vom Bundespräsidenten / von der Bundespräsidentin","eine Benachrichtigung von der Bundesversammlung","eine Benachrichtigung vom Pfarramt"],"correct":0,"explanation":"Vor jeder Wahl schickt die Gemeinde eine Wahlbenachrichtigung. Darin stehen das Wahllokal, der Wahltag und die Möglichkeit, Briefwahl zu beantragen.","region":"de"},{"number":127,"question":"Warum gibt es die 5 %-Hürde im Wahlgesetz der Bundesrepublik Deutschland? Es gibt sie, weil …","answers":["die Programme von vielen kleinen Parteien viele Gemeinsamkeiten haben.","die Bürger und Bürgerinnen bei vielen kleinen Parteien die Orientierung verlieren können.","viele kleine Parteien die Regierungsbildung erschweren.","die kleinen Parteien nicht so viel Geld haben, um die Politiker und Politikerinnen zu bezahlen."],"correct":2,"explanation":"Die Fünf-Prozent-Hürde soll verhindern, dass sehr viele kleine Parteien ins Parlament einziehen und stabile Mehrheiten unmöglich machen. Das Vorbild ist die Erfahrung mit der Weimarer Republik.","region":"de"},{"number":128,"question":"Parlamentsmitglieder, die von den Bürgern und Bürgerinnen gewählt werden, nennt man …","answers":["Abgeordnete.","Kanzler / Kanzlerinnen.","Botschafter / Botschafterinnen.","Ministerpräsidenten / Ministerpräsidentinnen."],"correct":0,"explanation":"Gewählte Mitglieder eines Parlaments heißen Abgeordnete. Sie sind nach dem Grundgesetz nur ihrem Gewissen unterworfen und an Aufträge nicht gebunden.","region":"de"},{"number":129,"question":"Vom Volk gewählt wird in Deutschland …","answers":["der Bundeskanzler / die Bundeskanzlerin.","der Ministerpräsident / die Ministerpräsidentin eines Bundeslandes.","der Bundestag.","der Bundespräsident / die Bundespräsidentin."],"correct":2,"explanation":"Direkt vom Volk gewählt wird auf Bundesebene nur der Bundestag. Kanzler, Bundespräsident und Ministerpräsidenten werden von Parlamenten beziehungsweise der Bundesversammlung gewählt.","region":"de"},{"number":130,"question":"Welcher Stimmzettel wäre bei einer Bundestagswahl gültig?","image":"assets/130-stimmzettel.png","answers":["1","2","3","4"],"correct":0,"explanation":"Gültig ist ein Stimmzettel, wenn genau ein Kreuz bei der Erststimme und genau ein Kreuz bei der Zweitstimme gesetzt ist und der Wille eindeutig erkennbar ist. Zusätze oder mehrere Kreuze machen ihn ungültig.","region":"de"},{"number":131,"question":"In Deutschland ist ein Bürgermeister / eine Bürgermeisterin …","answers":["der Leiter / die Leiterin einer Schule.","der Chef / die Chefin einer Bank.","das Oberhaupt einer Gemeinde.","der / die Vorsitzende einer Partei."],"correct":2,"explanation":"Der Bürgermeister oder die Bürgermeisterin ist das Oberhaupt einer Gemeinde und wird dort meist direkt gewählt. In größeren Städten heißt das Amt Oberbürgermeister.","region":"de"},{"number":132,"question":"Viele Menschen in Deutschland arbeiten in ihrer Freizeit ehrenamtlich. Was bedeutet das?","answers":["Sie arbeiten als Soldaten / Soldatinnen.","Sie arbeiten freiwillig und unbezahlt in Vereinen und Verbänden.","Sie arbeiten in der Bundesregierung.","Sie arbeiten in einem Krankenhaus und verdienen dabei Geld."],"correct":1,"explanation":"Ehrenamtlich heißt freiwillig und unbezahlt, zum Beispiel in Vereinen, bei der Feuerwehr oder in sozialen Einrichtungen. In Deutschland engagiert sich etwa jede dritte Person ehrenamtlich.","region":"de"},{"number":133,"question":"Was ist bei Bundestags- und Landtagswahlen in Deutschland erlaubt?","answers":["Der Ehemann wählt für seine Frau mit.","Man kann durch Briefwahl seine Stimme abgeben.","Man kann am Wahltag telefonisch seine Stimme abgeben.","Kinder ab dem Alter von 14 Jahren dürfen wählen."],"correct":1,"explanation":"Sie können Ihre Stimme persönlich im Wahllokal oder per Briefwahl abgeben. Die Briefwahl muss vorher beantragt werden. Wählen für andere Personen ist nicht erlaubt.","region":"de"},{"number":134,"question":"Man will die Buslinie abschaffen, mit der Sie immer zur Arbeit fahren. Was können Sie machen, um die Buslinie zu erhalten?","answers":["Ich beteilige mich an einer Bürgerinitiative für die Erhaltung der Buslinie oder gründe selber eine Initiative.","Ich werde Mitglied in einem Sportverein und trainiere Radfahren.","Ich wende mich an das Finanzamt, weil ich als Steuerzahler / Steuerzahlerin ein Recht auf die Buslinie habe.","Ich schreibe einen Brief an das Forstamt der Gemeinde."],"correct":0,"explanation":"Eine Bürgerinitiative ist ein Zusammenschluss von Menschen, die ein konkretes örtliches Anliegen durchsetzen wollen. Sie ist ein typisches Mittel der Beteiligung zwischen den Wahlen.","region":"de"},{"number":135,"question":"Wen vertreten die Gewerkschaften in Deutschland?","answers":["große Unternehmen","kleine Unternehmen","Selbständige","Arbeitnehmer und Arbeitnehmerinnen"],"correct":3,"explanation":"Gewerkschaften vertreten Arbeitnehmerinnen und Arbeitnehmer gegenüber den Arbeitgebern. Selbständige und Unternehmen organisieren sich dagegen in Kammern und Verbänden.","region":"de"},{"number":136,"question":"Sie gehen in Deutschland zum Arbeitsgericht bei …","answers":["falscher Nebenkostenabrechnung.","ungerechtfertigter Kündigung durch Ihren Chef / Ihre Chefin.","Problemen mit den Nachbarn / Nachbarinnen.","Schwierigkeiten nach einem Verkehrsunfall."],"correct":1,"explanation":"Für Streit aus dem Arbeitsverhältnis, etwa bei einer Kündigung, ist das Arbeitsgericht zuständig. Mietstreit gehört vor das Amtsgericht, Nachbarschaftsstreit ebenfalls.","region":"de"},{"number":137,"question":"Welches Gericht ist in Deutschland bei Konflikten in der Arbeitswelt zuständig?","answers":["das Familiengericht","das Strafgericht","das Arbeitsgericht","das Amtsgericht"],"correct":2,"explanation":"Konflikte zwischen Arbeitgebern und Arbeitnehmern entscheidet das Arbeitsgericht. Deutschland kennt neben der ordentlichen Gerichtsbarkeit mehrere Fachgerichtsbarkeiten für bestimmte Rechtsgebiete.","region":"de"},{"number":138,"question":"Was kann ich in Deutschland machen, wenn mir mein Arbeitgeber / meine Arbeitgeberin zu Unrecht gekündigt hat?","answers":["weiter arbeiten und freundlich zum Chef / zur Chefin sein","ein Mahnverfahren gegen den Arbeitgeber / die Arbeitgeberin führen","Kündigungsschutzklage erheben","den Arbeitgeber / die Arbeitgeberin bei der Polizei anzeigen"],"correct":2,"explanation":"Gegen eine Kündigung können Sie innerhalb von drei Wochen Kündigungsschutzklage beim Arbeitsgericht erheben. Diese Frist ist kurz, deshalb sollten Sie schnell handeln.","region":"de"},{"number":139,"question":"Wann kommt es in Deutschland zu einem Prozess vor Gericht? Wenn jemand …","answers":["zu einer anderen Religion übertritt.","eine Straftat begangen hat und angeklagt wird.","eine andere Meinung als die der Regierung vertritt.","sein Auto falsch geparkt hat und es abgeschleppt wird."],"correct":1,"explanation":"Zu einem Strafprozess kommt es, wenn die Staatsanwaltschaft jemanden wegen einer Straftat anklagt. Eine andere Meinung oder ein Religionswechsel sind keine Straftaten.","region":"de"},{"number":140,"question":"Was macht ein Schöffe / eine Schöffin in Deutschland? Er / Sie …","answers":["entscheidet mit Richtern / Richterinnen über Schuld und Strafe.","gibt Bürgern / Bürgerinnen rechtlichen Rat.","stellt Urkunden aus.","verteidigt den Angeklagten / die Angeklagte."],"correct":0,"explanation":"Schöffinnen und Schöffen sind ehrenamtliche Richter. Sie entscheiden zusammen mit den Berufsrichtern über Schuld und Strafe und haben dabei das gleiche Stimmrecht.","region":"de"},{"number":141,"question":"Wer berät in Deutschland Personen bei Rechtsfragen und vertritt sie vor Gericht?","answers":["ein Rechtsanwalt / eine Rechtsanwältin","ein Richter / eine Richterin","ein Schöffe / eine Schöffin","ein Staatsanwalt / eine Staatsanwältin"],"correct":0,"explanation":"Rechtsanwältinnen und Rechtsanwälte beraten Mandanten und vertreten sie vor Gericht. Richter entscheiden, Staatsanwälte klagen an, Schöffen urteilen ehrenamtlich mit.","region":"de"},{"number":142,"question":"Was ist die Hauptaufgabe eines Richters / einer Richterin in Deutschland? Ein Richter / eine Richterin …","answers":["vertritt Bürger und Bürgerinnen vor einem Gericht.","arbeitet an einem Gericht und spricht Urteile.","ändert Gesetze.","betreut Jugendliche vor Gericht."],"correct":1,"explanation":"Richterinnen und Richter sprechen Urteile und sind dabei unabhängig und nur an das Gesetz gebunden. Gesetze ändern können sie nicht, das ist Aufgabe des Parlaments.","region":"de"},{"number":143,"question":"Ein Richter / eine Richterin in Deutschland gehört zur …","answers":["Judikative.","Exekutive.","Operative.","Legislative."],"correct":0,"explanation":"Richter gehören zur Judikative, der rechtsprechenden Gewalt. Legislative ist die Gesetzgebung, Exekutive die Regierung und Verwaltung.","region":"de"},{"number":144,"question":"Ein Richter / eine Richterin gehört in Deutschland zur …","answers":["vollziehenden Gewalt.","rechtsprechenden Gewalt.","planenden Gewalt.","gesetzgebenden Gewalt."],"correct":1,"explanation":"Auf Deutsch heißt die Judikative rechtsprechende Gewalt. Vollziehende Gewalt ist die Exekutive, gesetzgebende Gewalt die Legislative.","region":"de"},{"number":145,"question":"In Deutschland wird die Staatsgewalt geteilt. Für welche Staatsgewalt arbeitet ein Richter / eine Richterin? Für die …","answers":["Judikative.","Exekutive.","Presse.","Legislative."],"correct":0,"explanation":"Richterinnen und Richter arbeiten für die Judikative. Ihre Unabhängigkeit von Regierung und Parlament ist eine Grundbedingung des Rechtsstaats.","region":"de"},{"number":146,"question":"Wie nennt man in Deutschland ein Verfahren vor einem Gericht?","answers":["Programm","Prozedur","Protokoll","Prozess"],"correct":3,"explanation":"Ein Verfahren vor Gericht heißt Prozess. Es gibt unter anderem Strafprozesse, Zivilprozesse und Arbeitsgerichtsprozesse.","region":"de"},{"number":147,"question":"Was ist die Arbeit eines Richters / einer Richterin in Deutschland?","answers":["Deutschland regieren","Recht sprechen","Pläne erstellen","Gesetze erlassen"],"correct":1,"explanation":"Die Arbeit von Richterinnen und Richtern besteht darin, Recht zu sprechen, also Gesetze auf den Einzelfall anzuwenden. Gesetze erlassen dagegen die Parlamente.","region":"de"},{"number":148,"question":"Was ist eine Aufgabe der Polizei in Deutschland?","answers":["das Land zu verteidigen","die Bürgerinnen und Bürger abzuhören","die Gesetze zu beschließen","die Einhaltung von Gesetzen zu überwachen"],"correct":3,"explanation":"Die Polizei überwacht die Einhaltung der Gesetze, schützt die Bevölkerung und verfolgt Straftaten. Die Landesverteidigung ist Aufgabe der Bundeswehr, Gesetze beschließt das Parlament.","region":"de"},{"number":149,"question":"Was ist ein Beispiel für antisemitisches Verhalten?","answers":["ein jüdisches Fest besuchen","die israelische Regierung kritisieren","den Holocaust leugnen","gegen Juden Fußball spielen"],"correct":2,"explanation":"Die Leugnung des Holocaust ist ein klares Beispiel für Antisemitismus und in Deutschland zusätzlich strafbar. Sachliche Kritik an der israelischen Regierung ist dagegen erlaubt und nicht antisemitisch.","region":"de"},{"number":150,"question":"Ein Gerichtsschöffe / eine Gerichtsschöffin in Deutschland ist …","answers":["der Stellvertreter / die Stellvertreterin des Stadtoberhaupts.","ein ehrenamtlicher Richter / eine ehrenamtliche Richterin.","ein Mitglied eines Gemeinderats.","eine Person, die Jura studiert hat."],"correct":1,"explanation":"Schöffinnen und Schöffen sind ehrenamtliche Richterinnen und Richter aus der Mitte der Bevölkerung. Ein Jurastudium ist dafür nicht erforderlich.","region":"de"},{"number":151,"question":"Wer baute die Mauer in Berlin?","answers":["Großbritannien","die Bundesrepublik Deutschland","die DDR","die USA"],"correct":2,"explanation":"Die Mauer wurde 1961 von der DDR gebaut, um die Massenflucht in den Westen zu stoppen. Bis dahin hatten rund 2,7 Millionen Menschen die DDR verlassen.","region":"de"},{"number":152,"question":"Wann waren die Nationalsozialisten mit Adolf Hitler in Deutschland an der Macht?","answers":["1918 bis 1923","1932 bis 1950","1933 bis 1945","1945 bis 1989"],"correct":2,"explanation":"Die nationalsozialistische Diktatur dauerte von der Ernennung Hitlers zum Reichskanzler am 30. Januar 1933 bis zur Kapitulation im Mai 1945.","region":"de"},{"number":153,"question":"Was war am 8. Mai 1945?","answers":["Tod Adolf Hitlers","Beginn des Berliner Mauerbaus","Wahl von Konrad Adenauer zum Bundeskanzler","Ende des Zweiten Weltkriegs in Europa"],"correct":3,"explanation":"Am 8. Mai 1945 endete mit der bedingungslosen Kapitulation der Wehrmacht der Zweite Weltkrieg in Europa. Der Tag wird heute als Tag der Befreiung begangen.","region":"de"},{"number":154,"question":"Wann war der Zweite Weltkrieg zu Ende?","answers":["1933","1945","1949","1961"],"correct":1,"explanation":"Der Zweite Weltkrieg endete 1945: in Europa am 8. Mai, in Asien im September nach der Kapitulation Japans.","region":"de"},{"number":155,"question":"Wann waren die Nationalsozialisten in Deutschland an der Macht?","answers":["1888 bis 1918","1921 bis 1934","1933 bis 1945","1949 bis 1963"],"correct":2,"explanation":"Die Nationalsozialisten waren von 1933 bis 1945 an der Macht. Merken Sie sich diese Jahreszahlen, sie kommen im Test mehrfach vor.","region":"de"},{"number":156,"question":"In welchem Jahr wurde Hitler Reichskanzler?","answers":["1923","1927","1933","1936"],"correct":2,"explanation":"Hitler wurde am 30. Januar 1933 von Reichspräsident Hindenburg zum Reichskanzler ernannt. Innerhalb weniger Monate baute er die Republik zur Diktatur um.","region":"de"},{"number":157,"question":"Die Nationalsozialisten mit Adolf Hitler errichteten 1933 in Deutschland …","answers":["eine Diktatur.","einen demokratischen Staat.","eine Monarchie.","ein Fürstentum."],"correct":0,"explanation":"Nach 1933 wurden Parteien verboten, Gewerkschaften zerschlagen und Grundrechte außer Kraft gesetzt. Aus der Demokratie der Weimarer Republik wurde eine Diktatur.","region":"de"},{"number":158,"question":"Das „Dritte Reich“ war eine …","answers":["Diktatur.","Demokratie.","Monarchie.","Räterepublik."],"correct":0,"explanation":"Die Nationalsozialisten nannten ihren Staat „Drittes Reich“. Es war eine Diktatur mit nur einer erlaubten Partei, ohne freie Wahlen und ohne unabhängige Gerichte.","region":"de"},{"number":159,"question":"Was gab es in Deutschland nicht während der Zeit des Nationalsozialismus?","answers":["freie Wahlen","Pressezensur","willkürliche Verhaftungen","Verfolgung der Juden"],"correct":0,"explanation":"Freie Wahlen gab es im Nationalsozialismus nicht. Pressezensur, willkürliche Verhaftungen und die Verfolgung der Juden gehörten dagegen zum Alltag der Diktatur.","region":"de"},{"number":160,"question":"Welcher Krieg dauerte von 1939 bis 1945?","answers":["der Erste Weltkrieg","der Zweite Weltkrieg","der Vietnamkrieg","der Golfkrieg"],"correct":1,"explanation":"Der Zweite Weltkrieg dauerte von 1939 bis 1945. Er begann mit dem deutschen Überfall auf Polen am 1. September 1939.","region":"de"},{"number":161,"question":"Was kennzeichnete den NS-Staat? Eine Politik …","answers":["des staatlichen Rassismus","der Meinungsfreiheit","der allgemeinen Religionsfreiheit","der Entwicklung der Demokratie"],"correct":0,"explanation":"Der NS-Staat war auf staatlichem Rassismus aufgebaut. Die sogenannten Nürnberger Gesetze von 1935 machten die Verfolgung von Jüdinnen und Juden zum geltenden Recht.","region":"de"},{"number":162,"question":"Claus Schenk Graf von Stauffenberg wurde bekannt durch …","answers":["eine Goldmedaille bei den Olympischen Spielen 1936.","den Bau des Reichstagsgebäudes.","den Aufbau der Wehrmacht.","das Attentat auf Hitler am 20. Juli 1944."],"correct":3,"explanation":"Claus Schenk Graf von Stauffenberg verübte am 20. Juli 1944 ein Attentat auf Hitler. Der Anschlag scheiterte, Stauffenberg wurde noch in derselben Nacht erschossen.","region":"de"},{"number":163,"question":"In welchem Jahr zerstörten die Nationalsozialisten Synagogen und jüdische Geschäfte in Deutschland?","answers":["1925","1930","1938","1945"],"correct":2,"explanation":"In der Nacht vom 9. auf den 10. November 1938 zerstörten Nationalsozialisten Synagogen und jüdische Geschäfte. Diese Pogromnacht war ein Wendepunkt hin zur offenen Gewalt.","region":"de"},{"number":164,"question":"Was passierte am 9. November 1938 in Deutschland?","answers":["Mit dem Angriff auf Polen beginnt der Zweite Weltkrieg.","Die Nationalsozialisten verlieren eine Wahl und lösen den Reichstag auf.","Jüdische Geschäfte und Synagogen werden durch Nationalsozialisten und ihre Anhänger zerstört.","Hitler wird Reichspräsident und lässt alle Parteien verbieten."],"correct":2,"explanation":"Am 9. November 1938 fanden die Novemberpogrome statt: Synagogen brannten, jüdische Geschäfte wurden zerstört, Menschen wurden misshandelt und verschleppt.","region":"de"},{"number":165,"question":"Wie hieß der erste Bundeskanzler der Bundesrepublik Deutschland?","answers":["Konrad Adenauer","Kurt Georg Kiesinger","Helmut Schmidt","Willy Brandt"],"correct":0,"explanation":"Konrad Adenauer war von 1949 bis 1963 der erste Bundeskanzler der Bundesrepublik. Er prägte die Westbindung und die Aussöhnung mit Frankreich.","region":"de"},{"number":166,"question":"Bei welchen Demonstrationen in Deutschland riefen die Menschen „Wir sind das Volk“?","answers":["bei den Montagsdemonstrationen 1989 in der DDR","beim Arbeiteraufstand 1953 in der DDR","bei den Demonstrationen 1968 in der Bundesrepublik Deutschland","bei den Anti-Atomkraft-Demonstrationen 1985 in der Bundesrepublik Deutschland"],"correct":0,"explanation":"„Wir sind das Volk“ war der zentrale Ruf der Montagsdemonstrationen 1989 in Leipzig und anderen Städten der DDR. Die Proteste führten zum Fall der Mauer.","region":"de"},{"number":167,"question":"Welche Länder wurden nach dem Zweiten Weltkrieg in Deutschland als „Alliierte Besatzungsmächte“ bezeichnet?","answers":["Sowjetunion, Großbritannien, Polen, Schweden","Frankreich, Sowjetunion, Italien, Japan","USA, Sowjetunion, Spanien, Portugal","USA, Sowjetunion, Großbritannien, Frankreich"],"correct":3,"explanation":"Die vier Besatzungsmächte waren die USA, die Sowjetunion, Großbritannien und Frankreich. Sie teilten Deutschland 1945 in vier Zonen auf.","region":"de"},{"number":168,"question":"Welches Land war keine „Alliierte Besatzungsmacht“ in Deutschland?","answers":["USA","Sowjetunion","Frankreich","Japan"],"correct":3,"explanation":"Japan war selbst Kriegsgegner der Alliierten und keine Besatzungsmacht in Deutschland. Besatzungsmächte waren USA, Sowjetunion, Großbritannien und Frankreich.","region":"de"},{"number":169,"question":"Wann wurde die Bundesrepublik Deutschland gegründet?","answers":["1939","1945","1949","1951"],"correct":2,"explanation":"Die Bundesrepublik Deutschland wurde 1949 gegründet, als das Grundgesetz am 23. Mai in Kraft trat. Im selben Jahr entstand im Osten die DDR.","region":"de"},{"number":170,"question":"Was gab es während der Zeit des Nationalsozialismus in Deutschland?","answers":["das Recht zur freien Entfaltung der Persönlichkeit","Pressefreiheit","das Verbot von Parteien","den Schutz der Menschenwürde"],"correct":2,"explanation":"Im Nationalsozialismus wurden alle Parteien außer der NSDAP verboten. Pressefreiheit, freie Entfaltung und der Schutz der Menschenwürde existierten nicht.","region":"de"},{"number":171,"question":"Soziale Marktwirtschaft bedeutet, die Wirtschaft …","answers":["steuert sich allein nach Angebot und Nachfrage.","wird vom Staat geplant und gesteuert, Angebot und Nachfrage werden nicht berücksichtigt.","richtet sich nach der Nachfrage im Ausland.","richtet sich nach Angebot und Nachfrage, aber der Staat sorgt für einen sozialen Ausgleich."],"correct":3,"explanation":"Die soziale Marktwirtschaft verbindet freien Wettbewerb mit sozialem Ausgleich. Angebot und Nachfrage bestimmen die Preise, der Staat sichert aber Mindeststandards und hilft in Notlagen.","region":"de"},{"number":172,"question":"In welcher Besatzungszone wurde die DDR gegründet? In der …","answers":["amerikanischen Besatzungszone.","französischen Besatzungszone.","britischen Besatzungszone.","sowjetischen Besatzungszone."],"correct":3,"explanation":"Die DDR entstand 1949 auf dem Gebiet der sowjetischen Besatzungszone. Die drei westlichen Zonen wurden zur Bundesrepublik Deutschland.","region":"de"},{"number":173,"question":"Die Bundesrepublik Deutschland ist ein Gründungsmitglied …","answers":["des Nordatlantikpakts (NATO).","der Vereinten Nationen (VN).","der Europäischen Union (EU).","des Warschauer Pakts."],"correct":2,"explanation":"Die Bundesrepublik gehörte 1957 zu den sechs Gründerstaaten der Europäischen Wirtschaftsgemeinschaft, aus der später die EU wurde. Der NATO trat sie erst 1955 bei, den Vereinten Nationen 1973.","region":"de"},{"number":174,"question":"Wann wurde die DDR gegründet?","answers":["1947","1949","1953","1956"],"correct":1,"explanation":"Die DDR wurde am 7. Oktober 1949 gegründet, wenige Monate nach der Bundesrepublik. Sie bestand bis zum 3. Oktober 1990.","region":"de"},{"number":175,"question":"Wie viele Besatzungszonen gab es in Deutschland nach dem Zweiten Weltkrieg?","answers":["3","4","5","6"],"correct":1,"explanation":"Nach 1945 gab es vier Besatzungszonen, je eine für die USA, die Sowjetunion, Großbritannien und Frankreich. Berlin wurde zusätzlich in vier Sektoren geteilt.","region":"de"},{"number":176,"question":"Wie waren die Besatzungszonen Deutschlands nach 1945 verteilt?","image":"assets/176-besatzungszonen-deutschland.png","answers":["1=Großbritannien, 2=Sowjetunion, 3=Frankreich, 4=USA","1=Sowjetunion, 2=Großbritannien, 3=USA, 4=Frankreich","1=Großbritannien, 2=Sowjetunion, 3=USA, 4=Frankreich","1=Großbritannien, 2=USA, 3=Sowjetunion, 4=Frankreich"],"correct":2,"explanation":"Großbritannien hatte den Nordwesten, die Sowjetunion den Osten, die USA den Süden und Frankreich den Südwesten. Als Merkhilfe: Die Sowjetunion lag immer im Osten.","region":"de"},{"number":177,"question":"Welche deutsche Stadt wurde nach dem Zweiten Weltkrieg in vier Sektoren aufgeteilt?","answers":["München","Berlin","Dresden","Frankfurt/Oder"],"correct":1,"explanation":"Berlin lag mitten in der sowjetischen Zone, wurde aber selbst in vier Sektoren geteilt. Daraus entstand später die geteilte Stadt mit West- und Ost-Berlin.","region":"de"},{"number":178,"question":"Vom Juni 1948 bis zum Mai 1949 wurden die Bürger und Bürgerinnen von West-Berlin durch eine Luftbrücke versorgt. Welcher Umstand war dafür verantwortlich?","answers":["Für Frankreich war eine Versorgung der West-Berliner Bevölkerung mit dem Flugzeug kostengünstiger.","Die amerikanischen Soldaten / Soldatinnen hatten beim Landtransport Angst vor Überfällen.","Für Großbritannien war die Versorgung über die Luftbrücke schneller.","Die Sowjetunion unterbrach den gesamten Verkehr auf dem Landwege."],"correct":3,"explanation":"Die Sowjetunion sperrte 1948 alle Land- und Wasserwege nach West-Berlin. Die Westalliierten versorgten die Stadt daraufhin fast ein Jahr lang aus der Luft.","region":"de"},{"number":179,"question":"Wie endete der Zweite Weltkrieg in Europa offiziell?","answers":["mit dem Tod Adolf Hitlers","durch die bedingungslose Kapitulation Deutschlands","mit dem Rückzug der Deutschen aus den besetzten Gebieten","durch eine Revolution in Deutschland"],"correct":1,"explanation":"Der Krieg endete in Europa offiziell mit der bedingungslosen Kapitulation der deutschen Wehrmacht am 8. Mai 1945. Hitler hatte sich bereits am 30. April das Leben genommen.","region":"de"},{"number":180,"question":"Der erste Bundeskanzler der Bundesrepublik Deutschland war …","answers":["Ludwig Erhard.","Willy Brandt.","Konrad Adenauer.","Gerhard Schröder."],"correct":2,"explanation":"Erster Bundeskanzler war Konrad Adenauer von der CDU. Ludwig Erhard folgte ihm 1963, Willy Brandt wurde erst 1969 Kanzler.","region":"de"},{"number":181,"question":"Was wollte Willy Brandt mit seinem Kniefall 1970 im ehemaligen jüdischen Ghetto in Warschau ausdrücken?","image":"assets/181-willy-bandt-warschau.png","answers":["Er hat sich den ehemaligen Alliierten unterworfen.","Er bat Polen und die polnischen Juden um Vergebung.","Er zeigte seine Demut vor dem Warschauer Pakt.","Er sprach ein Gebet am Grab des Unbekannten Soldaten."],"correct":1,"explanation":"Mit dem Kniefall am Mahnmal des Warschauer Ghettos 1970 bat Bundeskanzler Willy Brandt um Vergebung für die deutschen Verbrechen. Die Geste wurde weltweit als Zeichen der Versöhnung verstanden.","region":"de"},{"number":182,"question":"Wie heißt das jüdische Gebetshaus?","answers":["Basilika","Moschee","Synagoge","Kirche"],"correct":2,"explanation":"Das jüdische Gebetshaus heißt Synagoge. Die Kirche gehört zum Christentum, die Moschee zum Islam, die Basilika ist eine besondere Kirchenform.","region":"de"},{"number":183,"question":"Wann war in der Bundesrepublik Deutschland das „Wirtschaftswunder“?","answers":["40er Jahre","50er Jahre","70er Jahre","80er Jahre"],"correct":1,"explanation":"Als Wirtschaftswunder bezeichnet man den schnellen wirtschaftlichen Aufschwung der Bundesrepublik in den 1950er Jahren. Aus dieser Zeit stammt auch die Anwerbung der ersten Gastarbeiter.","region":"de"},{"number":184,"question":"Auf welcher rechtlichen Grundlage wurde der Staat Israel gegründet?","answers":["eine Resolution der Vereinten Nationen","ein Beschluss des Zionistenkongresses","ein Vorschlag der Bundesregierung","ein Vorschlag der UdSSR"],"correct":0,"explanation":"Grundlage war der Teilungsplan der Vereinten Nationen von 1947. Auf dieser Basis wurde der Staat Israel am 14. Mai 1948 gegründet.","region":"de"},{"number":185,"question":"Wofür stand der Ausdruck „Eiserner Vorhang“? Für die Abschottung …","answers":["des Warschauer Pakts gegen den Westen.","Norddeutschlands gegen Süddeutschland.","Nazi-Deutschlands gegen die Alliierten.","Europas gegen die USA."],"correct":0,"explanation":"Eiserner Vorhang nannte man die abgeriegelte Grenze zwischen dem Ostblock und dem Westen während des Kalten Krieges. Die Berliner Mauer war ihr sichtbarster Teil.","region":"de"},{"number":186,"question":"Im Jahr 1953 gab es in der DDR einen Aufstand, an den lange Zeit in der Bundesrepublik Deutschland ein Feiertag erinnerte. Wann war das?","answers":["1. Mai","17. Juni","20. Juli","9. November"],"correct":1,"explanation":"Am 17. Juni 1953 wurde ein Arbeiteraufstand in der DDR mit sowjetischen Panzern niedergeschlagen. In der Bundesrepublik war der 17. Juni bis 1990 Nationalfeiertag.","region":"de"},{"number":187,"question":"Welcher deutsche Staat hatte eine schwarz-rot-goldene Flagge mit Hammer, Zirkel und Ährenkranz?","image":"assets/187-ddr-flagge.png","answers":["Preußen","Bundesrepublik Deutschland","DDR","„Drittes Reich“"],"correct":2,"explanation":"Die DDR-Flagge zeigte auf Schwarz-Rot-Gold zusätzlich Hammer, Zirkel und Ährenkranz. Sie symbolisierten Arbeiter, Intelligenz und Bauern.","region":"de"},{"number":188,"question":"In welchem Jahr wurde die Mauer in Berlin gebaut?","answers":["1953","1956","1959","1961"],"correct":3,"explanation":"Der Bau der Berliner Mauer begann am 13. August 1961. Sie teilte die Stadt 28 Jahre lang.","region":"de"},{"number":189,"question":"Wann baute die DDR die Mauer in Berlin?","answers":["1919","1933","1961","1990"],"correct":2,"explanation":"Die DDR baute die Mauer 1961. Geöffnet wurde sie am 9. November 1989.","region":"de"},{"number":190,"question":"Was bedeutet die Abkürzung DDR?","answers":["Dritter Deutscher Rundfunk","Die Deutsche Republik","Dritte Deutsche Republik","Deutsche Demokratische Republik"],"correct":3,"explanation":"DDR steht für Deutsche Demokratische Republik. Trotz des Namens gab es dort keine freien Wahlen und keine Gewaltenteilung.","region":"de"},{"number":191,"question":"Wann wurde die Mauer in Berlin für alle geöffnet?","answers":["1987","1989","1992","1995"],"correct":1,"explanation":"Die Mauer wurde am 9. November 1989 für alle geöffnet. Sie fiel nach wochenlangen friedlichen Massenprotesten in der DDR.","region":"de"},{"number":192,"question":"Welches heutige deutsche Bundesland gehörte früher zum Gebiet der DDR?","answers":["Brandenburg","Bayern","Saarland","Hessen"],"correct":0,"explanation":"Brandenburg gehörte zum Gebiet der DDR. Die fünf neuen Länder sind Brandenburg, Mecklenburg-Vorpommern, Sachsen, Sachsen-Anhalt und Thüringen.","region":"de"},{"number":193,"question":"Von 1961 bis 1989 war Berlin …","answers":["ohne Bürgermeister.","ein eigener Staat.","durch eine Mauer geteilt.","nur mit dem Flugzeug erreichbar."],"correct":2,"explanation":"Von 1961 bis 1989 war Berlin durch die Mauer geteilt. West-Berlin blieb erreichbar, aber nur über kontrollierte Transitwege.","region":"de"},{"number":194,"question":"Am 3. Oktober feiert man in Deutschland den Tag der Deutschen …","answers":["Einheit.","Nation.","Bundesländer.","Städte."],"correct":0,"explanation":"Der 3. Oktober ist Tag der Deutschen Einheit und der einzige bundesweit gesetzlich festgelegte Feiertag. Er erinnert an den Beitritt der DDR im Jahr 1990.","region":"de"},{"number":195,"question":"Welches heutige deutsche Bundesland gehörte früher zum Gebiet der DDR?","answers":["Hessen","Sachsen-Anhalt","Nordrhein-Westfalen","Saarland"],"correct":1,"explanation":"Sachsen-Anhalt gehörte zur DDR. Hessen, Nordrhein-Westfalen und das Saarland lagen dagegen im Westen.","region":"de"},{"number":196,"question":"Warum nennt man die Zeit im Herbst 1989 in der DDR „Die Wende“? In dieser Zeit veränderte sich die DDR politisch …","answers":["von einer Diktatur zur Demokratie.","von einer liberalen Marktwirtschaft zum Sozialismus.","von einer Monarchie zur Sozialdemokratie.","von einem religiösen Staat zu einem kommunistischen Staat."],"correct":0,"explanation":"Als Wende bezeichnet man den Übergang der DDR von der SED-Diktatur zur Demokratie im Herbst 1989. Sie führte 1990 zur Wiedervereinigung.","region":"de"},{"number":197,"question":"Welches heutige deutsche Bundesland gehörte früher zum Gebiet der DDR?","answers":["Thüringen","Hessen","Bayern","Bremen"],"correct":0,"explanation":"Thüringen gehörte zum Gebiet der DDR. Hessen, Bayern und Bremen lagen im Westen.","region":"de"},{"number":198,"question":"Welches heutige deutsche Bundesland gehörte früher zum Gebiet der DDR?","answers":["Bayern","Niedersachsen","Sachsen","Baden-Württemberg"],"correct":2,"explanation":"Sachsen gehörte zur DDR. Bayern, Niedersachsen und Baden-Württemberg gehörten zur Bundesrepublik.","region":"de"},{"number":199,"question":"Mit der Abkürzung „Stasi“ meinte man in der DDR …","answers":["das Parlament.","das Ministerium für Staatssicherheit.","eine regierende Partei.","das Ministerium für Volksbildung."],"correct":1,"explanation":"Stasi war die Abkürzung für das Ministerium für Staatssicherheit, den Geheimdienst der DDR. Es überwachte die eigene Bevölkerung mit einem großen Netz an Spitzeln.","region":"de"},{"number":200,"question":"Welches heutige deutsche Bundesland gehörte früher zum Gebiet der DDR?","answers":["Hessen","Schleswig-Holstein","Mecklenburg-Vorpommern","Saarland"],"correct":2,"explanation":"Mecklenburg-Vorpommern gehörte zur DDR. Hessen, Schleswig-Holstein und das Saarland lagen im Westen.","region":"de"},{"number":201,"question":"Welche der folgenden Auflistungen enthält nur Bundesländer, die zum Gebiet der früheren DDR gehörten?","answers":["Niedersachsen, Nordrhein-Westfalen, Hessen, Schleswig-Holstein, Brandenburg","Mecklenburg-Vorpommern, Brandenburg, Sachsen, Sachsen-Anhalt, Thüringen","Bayern, Baden-Württemberg, Rheinland-Pfalz, Thüringen, Sachsen","Sachsen, Thüringen, Hessen, Niedersachsen, Brandenburg"],"correct":1,"explanation":"Zum Gebiet der DDR gehörten Mecklenburg-Vorpommern, Brandenburg, Sachsen, Sachsen-Anhalt und Thüringen. Diese fünf Länder nennt man die neuen Bundesländer.","region":"de"},{"number":202,"question":"Zu wem gehörte die DDR im „Kalten Krieg“?","answers":["zu den Westmächten","zum Warschauer Pakt","zur NATO","zu den blockfreien Staaten"],"correct":1,"explanation":"Die DDR gehörte im Kalten Krieg zum Warschauer Pakt, dem Militärbündnis unter Führung der Sowjetunion. Die Bundesrepublik war Mitglied der NATO.","region":"de"},{"number":203,"question":"Wie hieß das Wirtschaftssystem der DDR?","answers":["Marktwirtschaft","Planwirtschaft","Angebot und Nachfrage","Kapitalismus"],"correct":1,"explanation":"Die DDR hatte eine zentrale Planwirtschaft: Der Staat gab vor, was in welchen Mengen produziert wurde. Angebot und Nachfrage spielten dabei keine Rolle.","region":"de"},{"number":204,"question":"Wie wurden die Bundesrepublik Deutschland und die DDR zu einem Staat?","answers":["Die Bundesrepublik Deutschland hat die DDR besetzt.","Die heutigen fünf östlichen Bundesländer sind der Bundesrepublik Deutschland beigetreten.","Die westlichen Bundesländer sind der DDR beigetreten.","Die DDR hat die Bundesrepublik Deutschland besetzt."],"correct":1,"explanation":"Die Wiedervereinigung erfolgte durch den Beitritt der fünf neuen Länder zur Bundesrepublik nach Artikel 23 des Grundgesetzes. Es gab also keine Besetzung und keinen neuen Staat.","region":"de"},{"number":205,"question":"Mit dem Beitritt der DDR zur Bundesrepublik Deutschland gehören die neuen Bundesländer nun auch …","answers":["zur Europäischen Union.","zum Warschauer Pakt.","zur OPEC.","zur Europäischen Verteidigungsgemeinschaft."],"correct":0,"explanation":"Mit dem Beitritt 1990 wurden die neuen Bundesländer automatisch Teil der Europäischen Gemeinschaft, aus der die EU hervorging. Der Warschauer Pakt löste sich 1991 auf.","region":"de"},{"number":206,"question":"Woran erinnern die sogenannten „Stolpersteine“ in Deutschland?","answers":["an berühmte deutsche Politikerinnen und Politiker","an die Opfer des Nationalsozialismus","an Verkehrstote","an bekannte jüdische Musiker"],"correct":1,"explanation":"Stolpersteine sind kleine Messingtafeln im Gehweg vor dem letzten selbst gewählten Wohnort von Opfern des Nationalsozialismus. Es gibt inzwischen über 100.000 davon in Europa.","region":"de"},{"number":207,"question":"In welchem Militärbündnis war die DDR Mitglied?","answers":["in der NATO","im Rheinbund","im Warschauer Pakt","im Europabündnis"],"correct":2,"explanation":"Die DDR war Mitglied im Warschauer Pakt. Dieses Militärbündnis war das östliche Gegenstück zur NATO.","region":"de"},{"number":208,"question":"Was war die „Stasi“?","answers":["der Geheimdienst im „Dritten Reich“","eine berühmte deutsche Gedenkstätte","der Geheimdienst der DDR","ein deutscher Sportverein während des Zweiten Weltkrieges"],"correct":2,"explanation":"Die Stasi war der Geheimdienst der DDR. Ihre Akten sind heute öffentlich einsehbar, Betroffene können Einsicht beantragen.","region":"de"},{"number":209,"question":"Welches war das Wappen der Deutschen Demokratischen Republik?","image":"assets/209-ddr-warpen.png","answers":["1","2","3","4"],"correct":3,"explanation":"Das Wappen der DDR zeigte Hammer und Zirkel im Ährenkranz. Es stand für Arbeiter, Intelligenz und Bauern.","region":"de"},{"number":210,"question":"Was ereignete sich am 17. Juni 1953 in der DDR?","answers":["der feierliche Beitritt zum Warschauer Pakt","landesweite Streiks und ein Volksaufstand","der 1. SED-Parteitag","der erste Besuch Fidel Castros"],"correct":1,"explanation":"Am 17. Juni 1953 streikten und demonstrierten in der DDR über eine Million Menschen. Sowjetische Panzer schlugen den Volksaufstand nieder.","region":"de"},{"number":211,"question":"Welcher Politiker steht für die „Ostverträge“?","answers":["Helmut Kohl","Willy Brandt","Michail Gorbatschow","Ludwig Erhard"],"correct":1,"explanation":"Die Ostverträge der frühen 1970er Jahre stehen für die Entspannungspolitik von Bundeskanzler Willy Brandt. Sein Leitsatz lautete Wandel durch Annäherung.","region":"de"},{"number":212,"question":"Wie heißt Deutschland mit vollem Namen?","answers":["Bundesstaat Deutschland","Bundesländer Deutschland","Bundesrepublik Deutschland","Bundesbezirk Deutschland"],"correct":2,"explanation":"Der vollständige Name lautet Bundesrepublik Deutschland, abgekürzt BRD oder heute meist einfach Deutschland.","region":"de"},{"number":213,"question":"Wie viele Einwohner hat Deutschland?","answers":["70 Millionen","78 Millionen","83 Millionen","90 Millionen"],"correct":2,"explanation":"Deutschland hat rund 83 Millionen Einwohnerinnen und Einwohner und ist damit das bevölkerungsreichste Land der Europäischen Union.","region":"de"},{"number":214,"question":"Welche Farben hat die deutsche Flagge?","answers":["schwarz-rot-gold","rot-weiß-schwarz","schwarz-rot-grün","schwarz-gelb-rot"],"correct":0,"explanation":"Die deutsche Flagge ist schwarz-rot-gold. Die Farben gehen auf die Freiheitsbewegung des 19. Jahrhunderts zurück und stehen für Demokratie und Einheit.","region":"de"},{"number":215,"question":"Wer wird als „Kanzler der Deutschen Einheit“ bezeichnet?","answers":["Gerhard Schröder","Helmut Kohl","Konrad Adenauer","Helmut Schmidt"],"correct":1,"explanation":"Helmut Kohl war 1990 Bundeskanzler und trieb die Wiedervereinigung voran. Deshalb wird er als Kanzler der Deutschen Einheit bezeichnet.","region":"de"},{"number":216,"question":"Welches Symbol ist im Plenarsaal des Deutschen Bundestages zu sehen?","image":"assets/216-bundestag-symbol.png","answers":["die Fahne der Stadt Berlin.","der Bundesadler.","der Reichsadler.","die Reichskrone."],"correct":1,"explanation":"Im Plenarsaal des Bundestages hängt der Bundesadler, umgangssprachlich „fette Henne“ genannt. Der Reichsadler und die Reichskrone sind historische Symbole und werden nicht mehr verwendet.","region":"de"},{"number":217,"question":"In welchem Zeitraum gab es die Deutsche Demokratische Republik (DDR)?","answers":["1919 bis 1927","1933 bis 1945","1949 bis 1990","1945 bis 1961"],"correct":2,"explanation":"Die DDR bestand von 1949 bis 1990, also gut 40 Jahre. Am 3. Oktober 1990 trat sie der Bundesrepublik bei.","region":"de"},{"number":218,"question":"Wie viele Bundesländer kamen bei der Wiedervereinigung 1990 zur Bundesrepublik Deutschland hinzu?","answers":["4","5","6","7"],"correct":1,"explanation":"1990 kamen fünf neue Bundesländer hinzu: Brandenburg, Mecklenburg-Vorpommern, Sachsen, Sachsen-Anhalt und Thüringen. Aus elf Ländern wurden 16.","region":"de"},{"number":219,"question":"Die Bundesrepublik Deutschland hat die Grenzen von heute seit …","answers":["1933.","1949.","1971.","1990."],"correct":3,"explanation":"Seit der Wiedervereinigung 1990 hat Deutschland seine heutigen Grenzen. Der Zwei-plus-Vier-Vertrag bestätigte sie völkerrechtlich.","region":"de"},{"number":220,"question":"Der 27. Januar ist in Deutschland ein offizieller Gedenktag. Woran erinnert dieser Tag?","answers":["an das Ende des Zweiten Weltkrieges","an die Verabschiedung des Grundgesetzes","an die Wiedervereinigung Deutschlands","an die Opfer des Nationalsozialismus (Tag der Befreiung des Vernichtungslagers Auschwitz)"],"correct":3,"explanation":"Der 27. Januar ist der Tag des Gedenkens an die Opfer des Nationalsozialismus. An diesem Tag wurde 1945 das Vernichtungslager Auschwitz befreit.","region":"de"},{"number":221,"question":"Deutschland ist Mitglied des Schengener Abkommens. Was bedeutet das?","answers":["Deutsche können in viele Länder Europas ohne Passkontrolle reisen.","Alle Menschen können ohne Personenkontrolle in Deutschland einreisen.","Deutsche können ohne Passkontrolle in jedes Land reisen.","Deutsche können in jedem Land mit dem Euro bezahlen."],"correct":0,"explanation":"Im Schengen-Raum entfallen die Kontrollen an den Binnengrenzen. Deutsche können deshalb in viele europäische Länder ohne Passkontrolle reisen, weltweit gilt das aber nicht.","region":"de"},{"number":222,"question":"Welches Land ist ein Nachbarland von Deutschland?","answers":["Ungarn","Portugal","Spanien","Schweiz"],"correct":3,"explanation":"Die Schweiz ist eines der neun Nachbarländer Deutschlands. Ungarn, Portugal und Spanien grenzen nicht an Deutschland.","region":"de"},{"number":223,"question":"Welches Land ist ein Nachbarland von Deutschland?","answers":["Rumänien","Bulgarien","Polen","Griechenland"],"correct":2,"explanation":"Polen ist Deutschlands östliches Nachbarland. Die neun Nachbarn sind Dänemark, Polen, Tschechien, Österreich, Schweiz, Frankreich, Luxemburg, Belgien und die Niederlande.","region":"de"},{"number":224,"question":"Was bedeutet die Abkürzung EU?","answers":["Europäische Unternehmen","Europäische Union","Einheitliche Union","Euro Union"],"correct":1,"explanation":"EU steht für Europäische Union. Sie entstand 1993 aus der Europäischen Gemeinschaft und umfasst heute 27 Mitgliedstaaten.","region":"de"},{"number":225,"question":"In welchem anderen Land gibt es eine große deutschsprachige Bevölkerung?","answers":["Tschechien","Norwegen","Spanien","Österreich"],"correct":3,"explanation":"In Österreich ist Deutsch die Amtssprache. Auch in der Schweiz, in Liechtenstein und in Teilen Belgiens und Italiens wird Deutsch gesprochen.","region":"de"},{"number":226,"question":"Welche ist die Flagge der Europäischen Union?","image":"assets/226-eu-flagge.png","answers":["1","2","3","4"],"correct":1,"explanation":"Die EU-Flagge zeigt zwölf goldene Sterne im Kreis auf blauem Grund. Die Zahl zwölf steht für Vollkommenheit, nicht für die Zahl der Mitgliedstaaten.","region":"de"},{"number":227,"question":"Welches Land ist ein Nachbarland von Deutschland?","answers":["Finnland","Dänemark","Norwegen","Schweden"],"correct":1,"explanation":"Dänemark ist Deutschlands einziger Nachbar im Norden. Norwegen, Schweden und Finnland haben keine gemeinsame Grenze mit Deutschland.","region":"de"},{"number":228,"question":"Wie wird der Beitritt der DDR zur Bundesrepublik Deutschland im Jahr 1990 allgemein genannt?","answers":["NATO-Osterweiterung","EU-Osterweiterung","Europäische Gemeinschaft","Deutsche Wiedervereinigung"],"correct":3,"explanation":"Der Beitritt der DDR zur Bundesrepublik am 3. Oktober 1990 heißt Deutsche Wiedervereinigung. NATO- und EU-Osterweiterung kamen erst später.","region":"de"},{"number":229,"question":"Welches Land ist ein Nachbarland von Deutschland?","answers":["Spanien","Bulgarien","Norwegen","Luxemburg"],"correct":3,"explanation":"Luxemburg grenzt im Westen an Deutschland. Spanien, Bulgarien und Norwegen sind keine Nachbarländer.","region":"de"},{"number":230,"question":"Das Europäische Parlament wird regelmäßig gewählt, nämlich alle …","answers":["5 Jahre.","6 Jahre.","7 Jahre.","8 Jahre."],"correct":0,"explanation":"Das Europäische Parlament wird alle fünf Jahre direkt gewählt. In Deutschland dürfen dabei auch EU-Bürgerinnen und EU-Bürger anderer Staaten mitwählen.","region":"de"},{"number":231,"question":"Was bedeutet der Begriff „europäische Integration“?","answers":["Damit sind amerikanische Einwanderer in Europa gemeint.","Der Begriff meint den Einwanderungsstopp nach Europa.","Damit sind europäische Auswanderer in den USA gemeint.","Der Begriff meint den Zusammenschluss europäischer Staaten zur EU."],"correct":3,"explanation":"Europäische Integration meint den immer engeren Zusammenschluss europäischer Staaten, wirtschaftlich und politisch. Aus der EWG von 1957 wurde so die heutige EU.","region":"de"},{"number":232,"question":"Wer wird bei der Europawahl gewählt?","answers":["die Europäische Kommission","die Länder, die in die EU eintreten dürfen","die europäische Verfassung","die Abgeordneten des Europäischen Parlaments"],"correct":3,"explanation":"Bei der Europawahl werden die Abgeordneten des Europäischen Parlaments gewählt. Die Europäische Kommission wird dagegen nicht direkt vom Volk gewählt.","region":"de"},{"number":233,"question":"Welches Land ist ein Nachbarland von Deutschland?","answers":["Tschechien","Bulgarien","Griechenland","Portugal"],"correct":0,"explanation":"Tschechien grenzt im Südosten an Deutschland. Bulgarien, Griechenland und Portugal haben keine gemeinsame Grenze mit Deutschland.","region":"de"},{"number":234,"question":"Wo ist der Sitz des Europäischen Parlaments?","answers":["London","Paris","Berlin","Straßburg"],"correct":3,"explanation":"Der offizielle Sitz des Europäischen Parlaments ist Straßburg. Dort finden die Plenarsitzungen statt.","region":"de"},{"number":235,"question":"Der französische Staatspräsident François Mitterrand und der deutsche Bundeskanzler Helmut Kohl gedenken in Verdun gemeinsam der Toten beider Weltkriege. Welches Ziel der Europäischen Union wird bei diesem Treffen deutlich?","image":"assets/235-francois-mitterrand.png","answers":["Freundschaft zwischen England und Deutschland","Reisefreiheit in alle Länder der EU","Frieden und Sicherheit in den Ländern der EU","einheitliche Feiertage in den Ländern der EU"],"correct":2,"explanation":"Das gemeinsame Gedenken in Verdun 1984 steht für das wichtigste Ziel der europäischen Einigung: dauerhafter Frieden zwischen Staaten, die sich zuvor bekriegt hatten.","region":"de"},{"number":236,"question":"Wie viele Mitgliedstaaten hat die EU heute?","answers":["21","23","25","27"],"correct":3,"explanation":"Die EU hat seit dem Austritt Großbritanniens 27 Mitgliedstaaten. Deutschland gehört zu den Gründungsmitgliedern.","region":"de"},{"number":237,"question":"2007 wurde das 50-jährige Jubiläum der „Römischen Verträge“ gefeiert. Was war der Inhalt der Verträge?","answers":["Beitritt Deutschlands zur NATO","Gründung der Europäischen Wirtschaftsgemeinschaft (EWG)","Verpflichtung Deutschlands zu Reparationsleistungen","Festlegung der Oder-Neiße-Linie als Ostgrenze"],"correct":1,"explanation":"Mit den Römischen Verträgen von 1957 gründeten sechs Staaten die Europäische Wirtschaftsgemeinschaft. Sie sind der Ursprung der heutigen EU.","region":"de"},{"number":238,"question":"An welchen Orten arbeitet das Europäische Parlament?","answers":["Paris, London und Den Haag","Straßburg, Luxemburg und Brüssel","Rom, Bern und Wien","Bonn, Zürich und Mailand"],"correct":1,"explanation":"Das Europäische Parlament arbeitet an drei Orten: Straßburg für die Plenarsitzungen, Brüssel für Ausschüsse und Luxemburg für die Verwaltung.","region":"de"},{"number":239,"question":"Durch welche Verträge schloss sich die Bundesrepublik Deutschland mit anderen Staaten zur Europäischen Wirtschaftsgemeinschaft zusammen?","answers":["durch die „Hamburger Verträge“","durch die „Römischen Verträge“","durch die „Pariser Verträge“","durch die „Londoner Verträge“"],"correct":1,"explanation":"Die Europäische Wirtschaftsgemeinschaft entstand 1957 durch die Römischen Verträge. Unterzeichnet wurden sie von Deutschland, Frankreich, Italien und den Benelux-Staaten.","region":"de"},{"number":240,"question":"Seit wann bezahlt man in Deutschland mit dem Euro in bar?","answers":["1995","1998","2002","2005"],"correct":2,"explanation":"Das Euro-Bargeld wurde am 1. Januar 2002 eingeführt. Als Buchgeld gab es den Euro bereits seit 1999.","region":"de"},{"number":241,"question":"Frau Seger bekommt ein Kind. Was muss sie tun, um Elterngeld zu erhalten?","answers":["Sie muss an ihre Krankenkasse schreiben.","Sie muss nichts tun, denn sie bekommt automatisch Elterngeld.","Sie muss einen Antrag bei der Elterngeldstelle stellen.","Sie muss das Arbeitsamt um Erlaubnis bitten."],"correct":2,"explanation":"Elterngeld muss beantragt werden, und zwar bei der zuständigen Elterngeldstelle. Es wird höchstens drei Monate rückwirkend gezahlt, ein früher Antrag lohnt sich also.","region":"de"},{"number":242,"question":"Wer entscheidet, ob ein Kind in Deutschland in den Kindergarten geht?","answers":["der Staat","die Bundesländer","die Eltern / die Erziehungsberechtigten","die Schulen"],"correct":2,"explanation":"Über den Kindergartenbesuch entscheiden die Eltern beziehungsweise Erziehungsberechtigten. Eine Kindergartenpflicht gibt es in Deutschland nicht, wohl aber einen Rechtsanspruch auf einen Platz.","region":"de"},{"number":243,"question":"Maik und Sybille wollen mit Freunden an ihrem deutschen Wohnort eine Demonstration auf der Straße abhalten. Was müssen sie vorher tun?","answers":["Sie müssen nichts tun. Man darf in Deutschland jederzeit überall demonstrieren.","Sie müssen die Demonstration anmelden.","Sie können gar nichts tun, denn Demonstrationen sind in Deutschland grundsätzlich verboten.","Maik und Sybille müssen einen neuen Verein gründen, weil nur Vereine demonstrieren dürfen."],"correct":1,"explanation":"Versammlungen unter freiem Himmel müssen in der Regel 48 Stunden vorher bei der Versammlungsbehörde angemeldet werden. Eine Genehmigung ist das nicht, die Versammlungsfreiheit bleibt ein Grundrecht.","region":"de"},{"number":244,"question":"Welchen Schulabschluss braucht man normalerweise, um an einer Universität in Deutschland ein Studium zu beginnen?","answers":["das Abitur","ein Diplom","die Prokura","eine Gesellenprüfung"],"correct":0,"explanation":"Für ein Universitätsstudium braucht man normalerweise das Abitur, also die allgemeine Hochschulreife. Auch beruflich Qualifizierte können unter bestimmten Bedingungen studieren.","region":"de"},{"number":245,"question":"Wer darf in Deutschland nicht als Paar zusammenleben?","answers":["Hans (20 Jahre) und Marie (19 Jahre)","Tom (20 Jahre) und Klaus (45 Jahre)","Sofie (35 Jahre) und Lisa (40 Jahre)","Anne (13 Jahre) und Tim (25 Jahre)"],"correct":3,"explanation":"Sexuelle Handlungen mit Kindern unter 14 Jahren sind in Deutschland strafbar. Bei erwachsenen Paaren spielen Altersunterschied und Geschlecht dagegen keine Rolle.","region":"de"},{"number":246,"question":"Ab welchem Alter ist man in Deutschland volljährig?","answers":["16","18","19","21"],"correct":1,"explanation":"Mit 18 Jahren wird man in Deutschland volljährig. Damit ist man voll geschäftsfähig, darf wählen und trägt die volle rechtliche Verantwortung.","region":"de"},{"number":247,"question":"Eine Frau ist schwanger. Sie ist kurz vor und nach der Geburt ihres Kindes vom Gesetz besonders beschützt. Wie heißt dieser Schutz?","answers":["Elternzeit","Geburtsvorbereitung","Mutterschutz","Wochenbett"],"correct":2,"explanation":"Der Mutterschutz gilt in der Regel sechs Wochen vor und acht Wochen nach der Geburt. In dieser Zeit besteht ein Beschäftigungsverbot und ein besonderer Kündigungsschutz.","region":"de"},{"number":248,"question":"Die Erziehung der Kinder ist in Deutschland vor allem Aufgabe …","answers":["des Staates.","der Eltern.","der Großeltern.","der Schulen."],"correct":1,"explanation":"Artikel 6 des Grundgesetzes bestimmt: Pflege und Erziehung der Kinder sind das natürliche Recht der Eltern und die zuerst ihnen obliegende Pflicht. Der Staat wacht nur darüber.","region":"de"},{"number":249,"question":"Wer ist in Deutschland hauptsächlich verantwortlich für die Kindererziehung?","answers":["der Staat","die Eltern","die Verwandten","die Schulen"],"correct":1,"explanation":"Hauptverantwortlich für die Erziehung sind die Eltern. Schule, Kindergarten und Staat unterstützen sie, ersetzen sie aber nicht.","region":"de"},{"number":250,"question":"In Deutschland hat man die besten Chancen auf einen gut bezahlten Arbeitsplatz, wenn man …","answers":["katholisch ist.","gut ausgebildet ist.","eine Frau ist.","Mitglied einer Partei ist."],"correct":1,"explanation":"Bildung und Ausbildung sind in Deutschland die wichtigsten Faktoren für gute Berufschancen. Religion, Geschlecht oder Parteimitgliedschaft dürfen dabei keine Rolle spielen.","region":"de"},{"number":251,"question":"Wenn man in Deutschland ein Kind schlägt, …","answers":["geht das niemanden etwas an.","geht das nur die Familie etwas an.","kann man dafür nicht bestraft werden.","kann man dafür bestraft werden."],"correct":3,"explanation":"Kinder haben in Deutschland ein Recht auf gewaltfreie Erziehung. Körperliche Bestrafung ist verboten und kann als Körperverletzung bestraft werden.","region":"de"},{"number":252,"question":"In Deutschland …","answers":["darf man zur gleichen Zeit nur mit einem Partner / einer Partnerin verheiratet sein.","kann man mehrere Ehepartner / Ehepartnerinnen gleichzeitig haben.","darf man nicht wieder heiraten, wenn man einmal verheiratet war.","darf eine Frau nicht wieder heiraten, wenn ihr Mann gestorben ist."],"correct":0,"explanation":"In Deutschland gilt die Einehe. Man darf zur gleichen Zeit nur mit einer Person verheiratet sein. Nach Scheidung oder Tod des Partners ist eine neue Ehe möglich.","region":"de"},{"number":253,"question":"Wo müssen Sie sich anmelden, wenn Sie in Deutschland umziehen?","answers":["beim Einwohnermeldeamt","beim Standesamt","beim Ordnungsamt","beim Gewerbeamt"],"correct":0,"explanation":"Nach einem Umzug müssen Sie sich innerhalb von zwei Wochen beim Einwohnermeldeamt der neuen Gemeinde anmelden. Das Standesamt ist für Geburten, Ehen und Sterbefälle zuständig.","region":"de"},{"number":254,"question":"In Deutschland dürfen Ehepaare sich scheiden lassen. Meistens müssen sie dazu das „Trennungsjahr“ einhalten. Was bedeutet das?","answers":["Der Scheidungsprozess dauert ein Jahr.","Mann und Frau sind ein Jahr verheiratet, dann ist die Scheidung möglich.","Das Besuchsrecht für die Kinder gilt ein Jahr.","Mann und Frau führen mindestens ein Jahr getrennt ihr eigenes Leben. Danach ist die Scheidung möglich."],"correct":3,"explanation":"Das Trennungsjahr bedeutet, dass die Eheleute mindestens ein Jahr getrennt leben, bevor die Scheidung möglich ist. Getrennt leben kann man auch innerhalb einer Wohnung.","region":"de"},{"number":255,"question":"Bei Erziehungsproblemen können Eltern in Deutschland Hilfe erhalten vom …","answers":["Ordnungsamt.","Schulamt.","Jugendamt.","Gesundheitsamt."],"correct":2,"explanation":"Das Jugendamt berät und unterstützt Eltern bei Erziehungsfragen und in Krisen. Die Beratung ist kostenlos und vertraulich.","region":"de"},{"number":256,"question":"Ein Ehepaar möchte in Deutschland ein Restaurant eröffnen. Was braucht es dazu unbedingt?","answers":["eine Erlaubnis der Polizei","eine Genehmigung einer Partei","eine Genehmigung des Einwohnermeldeamts","eine Gaststättenerlaubnis von der zuständigen Behörde"],"correct":3,"explanation":"Wer alkoholische Getränke ausschenkt, braucht eine Gaststättenerlaubnis von der zuständigen Behörde. Zusätzlich sind Gewerbeanmeldung und Hygienevorschriften zu beachten.","region":"de"},{"number":257,"question":"Eine erwachsene Frau möchte in Deutschland das Abitur nachholen. Das kann sie an …","answers":["einer Hochschule.","einem Abendgymnasium.","einer Hauptschule.","einer Privatuniversität."],"correct":1,"explanation":"Erwachsene können das Abitur am Abendgymnasium oder Kolleg nachholen. Das gehört zum zweiten Bildungsweg, für den es in Deutschland viele Angebote gibt.","region":"de"},{"number":258,"question":"Was darf das Jugendamt in Deutschland?","answers":["Es entscheidet, welche Schule das Kind besucht.","Es kann ein Kind, das geschlagen wird oder hungern muss, aus der Familie nehmen.","Es bezahlt das Kindergeld an die Eltern.","Es kontrolliert, ob das Kind einen Kindergarten besucht."],"correct":1,"explanation":"Wenn das Wohl eines Kindes ernsthaft gefährdet ist, kann das Jugendamt es in Obhut nehmen. Über eine dauerhafte Trennung von den Eltern entscheidet dann das Familiengericht.","region":"de"},{"number":259,"question":"Das Berufsinformationszentrum BIZ bei der Bundesagentur für Arbeit in Deutschland hilft bei der …","answers":["Rentenberechnung.","Lehrstellensuche.","Steuererklärung.","Krankenversicherung."],"correct":1,"explanation":"Das Berufsinformationszentrum BIZ der Agentur für Arbeit hilft bei Berufsorientierung und Lehrstellensuche. Die Nutzung ist kostenlos.","region":"de"},{"number":260,"question":"In Deutschland hat ein Kind in der Schule …","answers":["Recht auf unbegrenzte Freizeit.","Wahlfreiheit für alle Fächer.","Anspruch auf Schulgeld.","Anwesenheitspflicht."],"correct":3,"explanation":"Aus der Schulpflicht folgt die Anwesenheitspflicht im Unterricht. Wer fehlt, muss sich entschuldigen, unentschuldigtes Fehlen kann zu Bußgeldern führen.","region":"de"},{"number":261,"question":"Ein Mann möchte mit 30 Jahren in Deutschland sein Abitur nachholen. Wo kann er das tun? An …","answers":["einer Hochschule","einem Abendgymnasium","einer Hauptschule","einer Privatuniversität"],"correct":1,"explanation":"Auch mit 30 Jahren kann man das Abitur am Abendgymnasium nachholen. Der zweite Bildungsweg steht in Deutschland grundsätzlich jedem Alter offen.","region":"de"},{"number":262,"question":"Was bedeutet in Deutschland der Grundsatz der Gleichbehandlung?","answers":["Niemand darf z.B. wegen einer Behinderung benachteiligt werden.","Man darf andere Personen benachteiligen, wenn ausreichende persönliche Gründe hierfür vorliegen.","Niemand darf gegen Personen klagen, wenn sie benachteiligt wurden.","Es ist für alle Gesetz, benachteiligten Gruppen jährlich Geld zu spenden."],"correct":0,"explanation":"Der Grundsatz der Gleichbehandlung verbietet Benachteiligungen wegen Herkunft, Geschlecht, Religion, Alter, Behinderung oder sexueller Identität. Geregelt ist das im Allgemeinen Gleichbehandlungsgesetz.","region":"de"},{"number":263,"question":"In Deutschland sind Jugendliche ab 14 Jahren strafmündig. Das bedeutet: Jugendliche, die 14 Jahre und älter sind und gegen Strafgesetze verstoßen, …","answers":["werden bestraft.","werden wie Erwachsene behandelt.","teilen die Strafe mit ihren Eltern.","werden nicht bestraft."],"correct":0,"explanation":"Ab 14 Jahren ist man strafmündig und wird nach dem Jugendstrafrecht bestraft. Erst ab 21 Jahren gilt in der Regel das Erwachsenenstrafrecht.","region":"de"},{"number":264,"question":"Zu welchem Fest tragen Menschen in Deutschland bunte Kostüme und Masken?","answers":["am Rosenmontag","am Maifeiertag","beim Oktoberfest","an Pfingsten"],"correct":0,"explanation":"Der Rosenmontag ist der Höhepunkt des Karnevals, besonders im Rheinland. Menschen verkleiden sich mit Kostümen und Masken und feiern Umzüge.","region":"de"},{"number":265,"question":"Wohin muss man in Deutschland zuerst gehen, wenn man heiraten möchte?","answers":["zum Einwohnermeldeamt","zum Ordnungsamt","zur Agentur für Arbeit","zum Standesamt"],"correct":3,"explanation":"Eine Ehe wird in Deutschland beim Standesamt geschlossen. Nur die standesamtliche Trauung ist rechtsgültig, eine kirchliche Trauung kann zusätzlich folgen.","region":"de"},{"number":266,"question":"Wann beginnt die gesetzliche Nachtruhe in Deutschland?","answers":["wenn die Sonne untergeht","um 22 Uhr","wenn die Nachbarn schlafen gehen","um 0 Uhr, Mitternacht"],"correct":1,"explanation":"Die gesetzliche Nachtruhe gilt in der Regel von 22 bis 6 Uhr. In dieser Zeit muss die Lautstärke so gering sein, dass Nachbarn nicht gestört werden.","region":"de"},{"number":267,"question":"Eine junge Frau in Deutschland, 22 Jahre alt, lebt mit ihrem Freund zusammen. Die Eltern der Frau finden das nicht gut, weil ihnen der Freund nicht gefällt. Was können die Eltern tun?","answers":["Sie müssen die Entscheidung der volljährigen Tochter respektieren.","Sie haben das Recht, die Tochter in die elterliche Wohnung zurückzuholen.","Sie können zur Polizei gehen und die Tochter anzeigen.","Sie suchen einen anderen Mann für die Tochter."],"correct":0,"explanation":"Mit 18 Jahren ist man volljährig und entscheidet selbst über Wohnort und Partnerwahl. Eltern haben dann kein Recht mehr, darüber zu bestimmen.","region":"de"},{"number":268,"question":"Eine junge Frau will den Führerschein machen. Sie hat Angst vor der Prüfung, weil ihre Muttersprache nicht Deutsch ist. Was ist richtig?","answers":["Sie muss mindestens zehn Jahre in Deutschland leben, bevor sie den Führerschein machen kann.","Sie kann die Theorie-Prüfung vielleicht in ihrer Muttersprache machen. Es gibt mehr als zehn Sprachen zur Auswahl.","Wenn sie kein Deutsch kann, darf sie keinen Führerschein haben.","Sie muss den Führerschein in dem Land machen, in dem man ihre Sprache spricht."],"correct":1,"explanation":"Die theoretische Führerscheinprüfung kann in mehreren Fremdsprachen abgelegt werden, unter anderem auf Englisch, Türkisch, Arabisch und Russisch. Die praktische Prüfung findet auf Deutsch statt, notfalls mit Dolmetscher.","region":"de"},{"number":269,"question":"In Deutschland haben Kinder ab dem Alter von drei Jahren bis zur Ersteinschulung einen Anspruch auf …","answers":["monatliches Taschengeld.","einen Kindergartenplatz.","einen Platz in einem Sportverein.","einen Ferienpass."],"correct":1,"explanation":"Seit 2013 gibt es einen Rechtsanspruch auf einen Betreuungsplatz ab dem vollendeten ersten Lebensjahr, ab drei Jahren auf einen Kindergartenplatz. Beantragt wird er bei der Gemeinde.","region":"de"},{"number":270,"question":"Die Volkshochschule in Deutschland ist eine Einrichtung …","answers":["für den Religionsunterricht.","nur für Jugendliche.","zur Weiterbildung.","nur für Rentner und Rentnerinnen."],"correct":2,"explanation":"Volkshochschulen sind kommunale Einrichtungen der Erwachsenenbildung. Sie bieten Sprachkurse, Integrationskurse und berufliche Weiterbildung an und führen auch den Einbürgerungstest durch.","region":"de"},{"number":271,"question":"Was ist in Deutschland ein Brauch zu Weihnachten?","answers":["bunte Eier verstecken","einen Tannenbaum schmücken","sich mit Masken und Kostümen verkleiden","Kürbisse vor die Tür stellen"],"correct":1,"explanation":"Zu Weihnachten schmücken viele Familien einen Tannenbaum und beschenken sich. Gefeiert wird am 24. Dezember, gesetzliche Feiertage sind der 25. und 26. Dezember.","region":"de"},{"number":272,"question":"Welche Lebensform ist in Deutschland nicht erlaubt?","answers":["Mann und Frau sind geschieden und leben mit neuen Partnern zusammen.","Zwei Frauen leben zusammen.","Ein alleinerziehender Vater lebt mit seinen zwei Kindern zusammen.","Ein Mann ist mit zwei Frauen zur selben Zeit verheiratet."],"correct":3,"explanation":"Die Mehrehe ist in Deutschland verboten und strafbar. Gleichgeschlechtliche Paare, Alleinerziehende und Patchworkfamilien sind dagegen völlig legal.","region":"de"},{"number":273,"question":"Bei Erziehungsproblemen gehen Sie in Deutschland …","answers":["zum Arzt / zur Ärztin.","zum Gesundheitsamt.","zum Einwohnermeldeamt.","zum Jugendamt."],"correct":3,"explanation":"Bei Erziehungsproblemen ist das Jugendamt die richtige Anlaufstelle. Es bietet Beratung an, ohne dass daraus automatisch Konsequenzen folgen.","region":"de"},{"number":274,"question":"Sie haben in Deutschland absichtlich einen Brief geöffnet, der an eine andere Person adressiert ist. Was haben Sie nicht beachtet?","answers":["das Schweigerecht","das Briefgeheimnis","die Schweigepflicht","die Meinungsfreiheit"],"correct":1,"explanation":"Das Briefgeheimnis ist in Artikel 10 des Grundgesetzes geschützt. Fremde Post absichtlich zu öffnen ist strafbar.","region":"de"},{"number":275,"question":"Was braucht man in Deutschland für eine Ehescheidung?","answers":["die Einwilligung der Eltern","ein Attest eines Arztes / einer Ärztin","die Einwilligung der Kinder","die Unterstützung eines Anwalts / einer Anwältin"],"correct":3,"explanation":"Für eine Scheidung besteht Anwaltszwang: Mindestens einer der Ehepartner muss anwaltlich vertreten sein. Die Scheidung spricht dann das Familiengericht aus.","region":"de"},{"number":276,"question":"Was sollten Sie tun, wenn Sie von Ihrem Ansprechpartner / Ihrer Ansprechpartnerin in einer deutschen Behörde schlecht behandelt werden?","answers":["Ich kann nichts tun.","Ich muss mir diese Behandlung gefallen lassen.","Ich drohe der Person.","Ich kann mich beim Behördenleiter / bei der Behördenleiterin beschweren."],"correct":3,"explanation":"Sie können sich bei der Leitung der Behörde beschweren, gegebenenfalls auch bei der Aufsichtsbehörde oder mit einer Petition. Drohungen sind dagegen strafbar.","region":"de"},{"number":277,"question":"Eine Frau, die ein zweijähriges Kind hat, bewirbt sich in Deutschland um eine Stelle. Was ist ein Beispiel für Diskriminierung? Sie bekommt die Stelle nur deshalb nicht, weil sie …","answers":["kein Englisch spricht.","zu hohe Gehaltsvorstellungen hat.","keine Erfahrungen in diesem Beruf hat.","Mutter ist."],"correct":3,"explanation":"Eine Ablehnung allein wegen der Mutterschaft ist eine Benachteiligung wegen des Geschlechts und nach dem Allgemeinen Gleichbehandlungsgesetz verboten. Fehlende Qualifikation wäre dagegen ein zulässiger Grund.","region":"de"},{"number":278,"question":"Ein Mann im Rollstuhl hat sich auf eine Stelle als Buchhalter beworben. Was ist ein Beispiel für Diskriminierung? Er bekommt die Stelle nur deshalb nicht, weil er …","answers":["im Rollstuhl sitzt.","keine Erfahrung hat.","zu hohe Gehaltsvorstellungen hat.","kein Englisch spricht."],"correct":0,"explanation":"Eine Absage allein wegen einer Behinderung ist Diskriminierung. Entscheidend darf nur sein, ob die Person die Tätigkeit ausüben kann, notfalls mit angepasstem Arbeitsplatz.","region":"de"},{"number":279,"question":"In den meisten Mietshäusern in Deutschland gibt es eine „Hausordnung“. Was steht in einer solchen „Hausordnung“? Sie nennt …","answers":["Regeln für die Benutzung öffentlicher Verkehrsmittel.","alle Mieter und Mieterinnen im Haus.","Regeln, an die sich alle Bewohner und Bewohnerinnen halten müssen.","die Adresse des nächsten Ordnungsamtes."],"correct":2,"explanation":"Die Hausordnung enthält verbindliche Regeln für alle Bewohner eines Mietshauses, etwa zu Ruhezeiten, Treppenreinigung und Müll. Sie ist meist Teil des Mietvertrags.","region":"de"},{"number":280,"question":"Wenn Sie sich in Deutschland gegen einen falschen Steuerbescheid wehren wollen, müssen Sie …","answers":["nichts machen.","den Bescheid wegwerfen.","Einspruch einlegen.","warten, bis ein anderer Bescheid kommt."],"correct":2,"explanation":"Gegen einen Steuerbescheid können Sie innerhalb eines Monats Einspruch beim Finanzamt einlegen. Wer nichts tut, muss den Bescheid gegen sich gelten lassen.","region":"de"},{"number":281,"question":"Zwei Freunde wollen in ein öffentliches Schwimmbad in Deutschland. Beide haben eine dunkle Hautfarbe und werden deshalb nicht hineingelassen. Welches Recht wird in dieser Situation verletzt? Das Recht auf …","answers":["Meinungsfreiheit","Gleichbehandlung","Versammlungsfreiheit","Freizügigkeit"],"correct":1,"explanation":"Der Ausschluss wegen der Hautfarbe verletzt das Recht auf Gleichbehandlung. Das Allgemeine Gleichbehandlungsgesetz verbietet rassistische Benachteiligung auch bei privaten Dienstleistungen.","region":"de"},{"number":282,"question":"Welches Ehrenamt müssen deutsche Staatsbürger / Staatsbürgerinnen übernehmen, wenn sie dazu aufgefordert werden?","answers":["Vereinstrainer / Vereinstrainerin","Bibliotheksaufsicht","Wahlhelfer / Wahlhelferin","Lehrer / Lehrerin"],"correct":2,"explanation":"Deutsche Staatsangehörige können zum Ehrenamt als Wahlhelferin oder Wahlhelfer verpflichtet werden. Andere Ehrenämter sind dagegen immer freiwillig.","region":"de"},{"number":283,"question":"Was tun Sie, wenn Sie eine falsche Rechnung von einer deutschen Behörde bekommen?","answers":["Ich lasse die Rechnung liegen.","Ich lege Widerspruch bei der Behörde ein.","Ich schicke die Rechnung an die Behörde zurück.","Ich gehe mit der Rechnung zum Finanzamt."],"correct":1,"explanation":"Gegen einen fehlerhaften Bescheid einer Behörde legen Sie Widerspruch ein, in der Regel innerhalb eines Monats. Die Frist steht in der Rechtsbehelfsbelehrung am Ende des Bescheids.","region":"de"},{"number":284,"question":"Was man für die Arbeit können muss, ändert sich in der Zukunft sehr schnell. Was kann man tun?","answers":["Es ist egal, was man lernt.","Kinder lernen in der Schule alles, was im Beruf wichtig ist. Nach der Schule muss man nicht weiter lernen.","Erwachsene müssen auch nach der Ausbildung immer weiter lernen.","Alle müssen früher aufhören zu arbeiten, weil sich alles ändert."],"correct":2,"explanation":"Weil sich Berufsanforderungen schnell ändern, ist lebenslanges Lernen wichtig. Volkshochschulen, Kammern und die Agentur für Arbeit bieten dafür viele Weiterbildungen an.","region":"de"},{"number":285,"question":"Frau Frost arbeitet als fest angestellte Mitarbeiterin in einem Büro. Was muss sie nicht von ihrem Gehalt bezahlen?","answers":["Umsatzsteuer","Lohnsteuer","Beiträge zur Arbeitslosenversicherung","Beiträge zur Renten- und Krankenversicherung"],"correct":0,"explanation":"Vom Gehalt gehen Lohnsteuer und Sozialversicherungsbeiträge ab. Die Umsatzsteuer zahlt man dagegen beim Einkaufen, sie wird nicht vom Lohn abgezogen.","region":"de"},{"number":286,"question":"Welche Organisation in einer Firma hilft den Arbeitnehmern und Arbeitnehmerinnen bei Problemen mit dem Arbeitgeber / der Arbeitgeberin?","answers":["der Betriebsrat","der Betriebsprüfer / die Betriebsprüferin","die Betriebsgruppe","das Betriebsmanagement"],"correct":0,"explanation":"Der Betriebsrat vertritt die Beschäftigten gegenüber dem Arbeitgeber. Er wird von der Belegschaft gewählt und hat bei vielen Entscheidungen Mitbestimmungsrechte.","region":"de"},{"number":287,"question":"Sie möchten bei einer Firma in Deutschland Ihr Arbeitsverhältnis beenden. Was müssen Sie beachten?","answers":["die Gehaltszahlungen","die Arbeitszeit","die Kündigungsfrist","die Versicherungspflicht"],"correct":2,"explanation":"Bei einer eigenen Kündigung müssen Sie die Kündigungsfrist einhalten, die im Arbeits- oder Tarifvertrag steht. Die gesetzliche Grundfrist beträgt vier Wochen zum 15. oder zum Monatsende.","region":"de"},{"number":288,"question":"Woraus begründet sich Deutschlands besondere Verantwortung für Israel?","answers":["aus der Mitgliedschaft in der Europäischen Union (EU)","aus den nationalsozialistischen Verbrechen gegen Juden","aus dem Grundgesetz der Bundesrepublik Deutschland","aus der christlichen Tradition"],"correct":1,"explanation":"Deutschlands besondere Verantwortung für Israel folgt aus dem Holocaust, also den nationalsozialistischen Verbrechen an den europäischen Juden. Diese Verantwortung nennen Bundesregierungen seit Jahrzehnten Teil der deutschen Staatsräson.","region":"de"},{"number":289,"question":"Ein Mann mit dunkler Hautfarbe bewirbt sich um eine Stelle als Kellner in einem Restaurant in Deutschland. Was ist ein Beispiel für Diskriminierung? Er bekommt die Stelle nur deshalb nicht, weil …","answers":["seine Deutschkenntnisse zu gering sind.","er zu hohe Gehaltsvorstellungen hat.","er eine dunkle Haut hat.","er keine Erfahrungen im Beruf hat."],"correct":2,"explanation":"Eine Absage allein wegen der Hautfarbe ist rassistische Diskriminierung und verboten. Fehlende Sprachkenntnisse oder Berufserfahrung wären dagegen sachliche Gründe.","region":"de"},{"number":290,"question":"Sie haben in Deutschland einen Fernseher gekauft. Zu Hause packen Sie den Fernseher aus, doch er funktioniert nicht. Der Fernseher ist kaputt. Was können Sie machen?","answers":["eine Anzeige schreiben","den Fernseher reklamieren","das Gerät ungefragt austauschen","die Garantie verlängern"],"correct":1,"explanation":"Bei einem defekten Neugerät haben Sie ein Recht auf Nacherfüllung, also Reparatur oder Austausch. Dafür reklamieren Sie die Ware beim Verkäufer, die gesetzliche Gewährleistung beträgt zwei Jahre.","region":"de"},{"number":291,"question":"Warum muss man in Deutschland bei der Steuererklärung aufschreiben, ob man zu einer Kirche gehört oder nicht? Weil …","answers":["das für die Statistik in Deutschland wichtig ist.","es eine Kirchensteuer gibt, die an die Einkommen- und Lohnsteuer geknüpft ist.","man mehr Steuern zahlen muss, wenn man nicht zu einer Kirche gehört.","die Kirche für die Steuererklärung verantwortlich ist."],"correct":1,"explanation":"Für Mitglieder bestimmter Religionsgemeinschaften zieht der Staat die Kirchensteuer zusammen mit der Einkommensteuer ein. Wer keiner solchen Gemeinschaft angehört, zahlt sie nicht.","region":"de"},{"number":292,"question":"Die Menschen in Deutschland leben nach dem Grundsatz der religiösen Toleranz. Was bedeutet das?","answers":["Es dürfen keine Moscheen gebaut werden.","Alle Menschen glauben an Gott.","Jeder kann glauben, was er möchte.","Der Staat entscheidet, an welchen Gott die Menschen glauben."],"correct":2,"explanation":"Religiöse Toleranz bedeutet, dass jede Person glauben darf, was sie möchte, oder auch gar nicht zu glauben. Der Staat schreibt keine Religion vor.","region":"de"},{"number":293,"question":"Was ist in Deutschland ein Brauch an Ostern?","answers":["Kürbisse vor die Tür stellen","einen Tannenbaum schmücken","Eier bemalen","Raketen in die Luft schießen"],"correct":2,"explanation":"Zu Ostern werden Eier bemalt und versteckt. Ostern ist das wichtigste christliche Fest und erinnert an die Auferstehung Jesu.","region":"de"},{"number":294,"question":"Pfingsten ist ein …","answers":["christlicher Feiertag.","deutscher Gedenktag.","internationaler Trauertag.","bayerischer Brauch."],"correct":0,"explanation":"Pfingsten ist ein christlicher Feiertag 50 Tage nach Ostern. Pfingstmontag ist in ganz Deutschland gesetzlicher Feiertag.","region":"de"},{"number":295,"question":"Welche Religion hat die europäische und deutsche Kultur geprägt?","answers":["der Hinduismus","das Christentum","der Buddhismus","der Islam"],"correct":1,"explanation":"Das Christentum hat die europäische und deutsche Kultur am stärksten geprägt, sichtbar an Feiertagen, Kirchen und Rechtstraditionen. Heute ist Deutschland religiös vielfältig.","region":"de"},{"number":296,"question":"In Deutschland nennt man die letzten vier Wochen vor Weihnachten …","answers":["den Buß- und Bettag.","das Erntedankfest.","die Adventszeit.","Allerheiligen."],"correct":2,"explanation":"Die vier Wochen vor Weihnachten heißen Adventszeit. Typisch sind Adventskranz, Adventskalender und Weihnachtsmärkte.","region":"de"},{"number":297,"question":"Aus welchem Land sind die meisten Migranten / Migrantinnen nach Deutschland gekommen?","answers":["Italien","Polen","Marokko","Türkei"],"correct":3,"explanation":"Die größte Einwanderergruppe in Deutschland stammt aus der Türkei. Die Anwerbung begann mit dem Anwerbeabkommen von 1961.","region":"de"},{"number":298,"question":"In der DDR lebten vor allem Migranten aus …","answers":["Vietnam, Polen, Mosambik.","Frankreich, Rumänien, Somalia.","Chile, Ungarn, Simbabwe.","Nordkorea, Mexiko, Ägypten."],"correct":0,"explanation":"In der DDR arbeiteten Vertragsarbeiter vor allem aus Vietnam, Polen und Mosambik. Sie lebten meist getrennt von der übrigen Bevölkerung.","region":"de"},{"number":299,"question":"Ausländische Arbeitnehmer und Arbeitnehmerinnen, die in den 50er und 60er Jahren von der Bundesrepublik Deutschland angeworben wurden, nannte man …","answers":["Schwarzarbeiter / Schwarzarbeiterinnen","Gastarbeiter / Gastarbeiterinnen","Zeitarbeiter / Zeitarbeiterinnen","Schichtarbeiter / Schichtarbeiterinnen"],"correct":1,"explanation":"Die in den 1950er und 1960er Jahren angeworbenen ausländischen Arbeitskräfte nannte man Gastarbeiter. Viele blieben dauerhaft und holten ihre Familien nach.","region":"de"},{"number":300,"question":"Aus welchem Land kamen die ersten Gastarbeiter / Gastarbeiterinnen in die Bundesrepublik Deutschland?","answers":["Italien","Spanien","Portugal","Türkei"],"correct":0,"explanation":"Das erste Anwerbeabkommen schloss die Bundesrepublik 1955 mit Italien. Es folgten unter anderem Spanien, Griechenland und 1961 die Türkei.","region":"de"},{"number":321,"question":"Welches Wappen gehört zum Bundesland Berlin?","image":"assets/321-berlin-wappen.png","answers":["1","2","3","4"],"correct":3,"explanation":"Das Wappen von Berlin zeigt den schwarzen Berliner Bären auf weißem Grund. Prägen Sie sich das Bild gut ein, im Test wird nur das richtige Wappen gesucht.","region":"be"},{"number":322,"question":"Welches ist ein Bezirk von Berlin?","answers":["Altona","Prignitz","Pankow","Mecklenburgische Seenplatte"],"correct":2,"explanation":"Pankow ist einer der zwölf Bezirke Berlins. Die anderen Antworten nennen Gebiete aus anderen Bundesländern.","region":"be"},{"number":323,"question":"Für wie viele Jahre wird das Landesparlament in Berlin gewählt?","answers":["3","4","5","6"],"correct":2,"explanation":"Das Landesparlament (Abgeordnetenhaus) in Berlin wird für fünf Jahre gewählt. Der Bundestag wird dagegen nur für vier Jahre gewählt.","region":"be"},{"number":324,"question":"Ab welchem Alter darf man in Berlin bei Kommunalwahlen (Wahl der Bezirksverordnetenversammlung) wählen?","answers":["14","16","18","20"],"correct":1,"explanation":"In Berlin darf man bei Kommunalwahlen bereits ab 16 Jahren wählen. Das Wahlalter dafür legt jedes Bundesland selbst fest.","region":"be"},{"number":325,"question":"Welche Farben hat die Landesflagge von Berlin?","answers":["blau-weiß-rot","weiß-rot","grün-weiß-rot","schwarz-gold"],"correct":1,"explanation":"Die Landesflagge von Berlin ist weiß-rot. Verwechseln Sie sie nicht mit der Bundesflagge, die immer schwarz-rot-gold ist.","region":"be"},{"number":326,"question":"Wo können Sie sich in Berlin über politische Themen informieren?","answers":["beim Ordnungsamt der Gemeinde","bei den Kirchen","bei der Verbraucherzentrale","bei der Landeszentrale für politische Bildung"],"correct":3,"explanation":"Für politische Information ist die Landeszentrale für politische Bildung zuständig. Sie bietet in Berlin kostenlose Broschüren, Veranstaltungen und Materialien an.","region":"be"},{"number":327,"question":"Welches Bundesland ist ein Stadtstaat?","answers":["Berlin","Saarland","Brandenburg","Hessen"],"correct":0,"explanation":"Berlin ist ein Stadtstaat, also gleichzeitig Stadt und Bundesland. Die drei deutschen Stadtstaaten sind Berlin, Hamburg und Bremen.","region":"be"},{"number":328,"question":"Welches Bundesland ist Berlin?","image":"assets/328-welches-bundesland-berlin.png","answers":["1","2","3","4"],"correct":3,"explanation":"Berlin ist die Hauptstadt Deutschlands und liegt als Stadtstaat vollständig im Land Brandenburg. Suchen Sie auf der Karte die passende Form und Lage.","region":"be"},{"number":329,"question":"Wie nennt man den Regierungschef / die Regierungschefin des Stadtstaates Berlin?","answers":["Ministerpräsident / Ministerpräsidentin","Oberbürgermeister / Oberbürgermeisterin","Präsident / Präsidentin des Senats","Regierender Bürgermeister / Regierende Bürgermeisterin"],"correct":3,"explanation":"In Berlin heißt der Regierungschef oder die Regierungschefin Regierender Bürgermeister / Regierende Bürgermeisterin. Premierminister oder Erster Minister sind Bezeichnungen aus anderen Staaten.","region":"be"},{"number":330,"question":"Welchen Senator / welche Senatorin hat Berlin nicht?","answers":["Finanzsenator / Finanzsenatorin","Innensenator / Innensenatorin","Senator / Senatorin für Außenbeziehungen","Justizsenator / Justizsenatorin"],"correct":2,"explanation":"Außenpolitik ist allein Sache des Bundes. Kein Bundesland hat deshalb ein Außenministerium, wohl aber Senatorinnen und Senatoren für Finanzen, Inneres und Justiz.","region":"be"}];
